-- =====================================================================
-- MIGRAZIONE UNICA 027 + 028 — La guerra degli Eroi: nuove interazioni + dungeon 56–100 (accessibili fino al livello 600)
--   Un solo file, una sola esecuzione: contiene il motore delle interazioni (ex 027) e i 45 dungeon 56–100 (ex 028, già con i livelli fino al 600).
--   Dentro un'unica transazione: se qualcosa fallisce non resta niente a metà. Si può rieseguire senza danni (aggiorna livelli, XP e oggetti).
--   Se avevi già eseguito la 027 o una vecchia 028: nessun problema, questo file le sostituisce entrambe. NON serve eseguire altro.
-- ---------------------------------------------------------------------
-- PARTE 1 — motore delle interazioni (ex 027)
-- =====================================================================
-- MIGRAZIONE 027 — La guerra degli Eroi: nuovi tipi di interazione nei dungeon a scelte
--   Prepara il motore per i dungeon 56–100 (che arrivano con la migrazione 028). Non aggiunge dungeon e non cambia i 55 esistenti.
--   Nuovi tipi di interazione, tutti SEGRETI lato server come i bivi (il browser vede solo ciò che serve per giocare):
--     🎲 PROVA DI ABILITÀ   una scelta si risolve col dado: la probabilità dipende da come sono costruiti gli eroi del gruppo
--                          (punti in Forza/Destrezza/Vigore/Spirito/Fortezza) e viene mostrata prima di scegliere.
--     🔐 SERRATURA          una combinazione di simboli da indovinare in pochi tentativi: dopo ogni errore si sa quanti simboli
--                          sono al posto giusto; gli indizi per risolverla stanno nelle scene precedenti.
--     🧭 STANZA A PIÙ AZIONI  una scena in cui si possono fare più azioni «una tantum» (esplorare, curarsi, cercare) prima di proseguire.
--     👤 SCEGLI L'EROE      il capo gruppo sceglie QUALE eroe affronta la prova: l'esito dipende dal suo ruolo e il danno colpisce lui.
--     🛡️ SCELTE DI RUOLO    alcune opzioni esistono solo se nel gruppo c'è un Tank, un eroe Danni o un Supporto.
--     ⏳ OROLOGIO           alcuni dungeon hanno un numero limitato di mosse: finite quelle, arriva la fine (o un nemico peggiore).
--   Il capo gruppo usa sempre game_dungeon_choose: ora ha un terzo parametro facoltativo (la combinazione o l'eroe scelto).
--   I dungeon esistenti funzionano come prima. Non tocca saldi, registro, premi o progressi già scritti.
-- Da eseguire in Supabase (SQL Editor) DOPO la 026 (e dopo le migrazioni eroi successive). Si può rieseguire.
-- =====================================================================

begin;

-- ---------- effetti: ora anche l'orologio (clk) e i danni a UN solo eroe ----------
drop function if exists public._game_dng_fx(jsonb, jsonb);
create or replace function public._game_dng_fx(p_state jsonb, p_fx jsonb, p_who text default null) returns jsonb language plpgsql immutable set search_path = public as $$
declare st jsonb := p_state; mem jsonb := '[]'::jsonb; x jsonb; f text; pct numeric;
begin
  if p_fx is null or p_fx = 'null'::jsonb then return st; end if;
  if p_fx ? 'pow' then st := jsonb_set(st, '{pow}', to_jsonb(greatest(-50, least(100, (st->>'pow')::integer + (p_fx->>'pow')::integer)))); end if;
  if p_fx ? 'hp' then
    pct := (p_fx->>'hp')::numeric;
    for x in select * from jsonb_array_elements(st->'members') loop
      if (p_who is null or x->>'user_id' = p_who) and ((x->>'hp')::numeric > 0 or pct > 0) then
        x := jsonb_set(x, '{hp}', to_jsonb(round(greatest(1, least((x->>'mx')::numeric, (x->>'hp')::numeric + (x->>'mx')::numeric * pct / 100.0)), 2)));
      end if;
      mem := mem || jsonb_build_array(x);
    end loop;
    st := jsonb_set(st, '{members}', mem);
  end if;
  if p_fx ? 'flag' then
    f := p_fx->>'flag';
    if not (st->'flags') @> to_jsonb(f) then st := jsonb_set(st, '{flags}', (st->'flags') || to_jsonb(f)); end if;
  end if;
  if p_fx ? 'clk' and st ? 'clk' then st := jsonb_set(st, '{clk}', to_jsonb(greatest(0, (st->>'clk')::integer + (p_fx->>'clk')::integer))); end if;
  return st;
end $$;

-- ---------- probabilità di una prova di abilità ----------
-- base (%) + 0,8 × (quota di punti che il MIGLIORE del gruppo ha messo in quella caratteristica, meno il 20% di una distribuzione uniforme)
-- + 4% per ogni eroe in più; sempre tra il 5% e il 95%. Base ≥ 100 = riesce sempre, base ≤ 0 = non riesce mai (usati nei test).
create or replace function public._game_dng_odds(p_state jsonb, p_stat text, p_base numeric) returns numeric language plpgsql stable security definer set search_path = public as $$
declare best numeric := 0; x jsonb; sh numeric; h public.game_heroes%rowtype; tot numeric; a numeric; alive integer := 0;
begin
  if p_base >= 100 then return 1; end if;
  if p_base <= 0 then return 0; end if;
  for x in select * from jsonb_array_elements(p_state->'members') loop
    continue when (x->>'hp')::numeric <= 0;
    select * into h from public.game_heroes where user_id = (x->>'user_id')::uuid;
    continue when not found;
    alive := alive + 1;
    tot := greatest(1, h.a_for + h.a_des + h.a_vig + h.a_spi + h.a_frt);
    a := case p_stat when 'for' then h.a_for when 'des' then h.a_des when 'vig' then h.a_vig when 'spi' then h.a_spi when 'frt' then h.a_frt else 0 end;
    sh := a / tot;
    if sh > best then best := sh; end if;
  end loop;
  return least(0.95, greatest(0.05, p_base / 100.0 + 0.8 * (best - 0.2) + 0.04 * greatest(0, alive - 1)));
end $$;

-- ---------- ciò che il giocatore vede ----------
create or replace function public._game_dng_view(p_run uuid) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare r public.game_runs%rowtype; g jsonb; nd jsonb; st jsonb; fl text[]; roles text[]; opts jsonb := '[]'::jsonb; o jsonb; txt text; lock_ boolean; hint text; lbl jsonb; used jsonb;
  od integer; lk jsonb; clk jsonb; done_ boolean;
begin
  select * into r from public.game_runs where id = p_run;
  if not found or r.state is null then return null; end if;
  st := r.state;
  select graph into g from public.game_dungeon_graphs where dungeon_no = r.dungeon_no;
  nd := g->(st->>'node');
  select coalesce(array_agg(f), '{}') into fl from jsonb_array_elements_text(st->'flags') f;
  select coalesce(array_agg(distinct m->>'role'), '{}') into roles from jsonb_array_elements(st->'members') m;
  lbl := coalesce(g->'_flags', '{}'::jsonb);
  used := coalesce(st->'used', '[]'::jsonb);
  if nd is not null and nd->>'t' in ('scene', 'lock') then
    txt := nd->>'x';
    if nd ? 'h' and (nd->'h'->>'if') = any(fl) then txt := txt || E'\n\n' || (nd->'h'->>'t'); end if;
  end if;
  if nd is not null and nd->>'t' = 'scene' then
    for o in select * from jsonb_array_elements(nd->'o') loop
      continue when o ? 'only' and not coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(o->'only') f), true);
      lock_ := o ? 'req' and not coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(o->'req') f), true);
      hint := null;
      if lock_ then hint := 'Ti serve: ' || (select string_agg(coalesce(lbl->>f, f), ', ') from jsonb_array_elements_text(o->'req') f); end if;
      if o ? 'role' and not (o->>'role' = any(roles)) then
        lock_ := true;
        hint := 'Serve ' || case o->>'role' when 'tank' then 'un Tank' when 'dps' then 'un eroe Danni' else 'un Supporto' end || ' nel gruppo';
      end if;
      done_ := coalesce((o->>'stay')::boolean, false) and used @> to_jsonb((st->>'node') || ':' || (o->>'id'));
      if done_ then lock_ := true; hint := 'Già fatto'; end if;
      od := null;
      if o ? 'chk' then od := round(100 * public._game_dng_odds(st, o->'chk'->>'s', (o->'chk'->>'b')::numeric))::integer; end if;
      opts := opts || jsonb_build_array(jsonb_build_object('id', o->>'id', 'label', o->>'l', 'locked', lock_, 'hint', hint,
                'chk', case when o ? 'chk' then jsonb_build_object('stat', o->'chk'->>'s', 'odds', od) else null end,
                'who', coalesce((o->>'who')::boolean, false), 'stay', coalesce((o->>'stay')::boolean, false), 'role', o->>'role', 'done', done_));
    end loop;
  end if;
  if nd is not null and nd->>'t' = 'lock' then
    lk := jsonb_build_object('symbols', nd->'sym', 'len', jsonb_array_length(nd->'code'),
            'tries_left', greatest(0, (nd->>'tries')::integer - coalesce((st->'lk'->>(st->>'node'))::integer, 0)), 'feedback', st->'lkf');
  end if;
  if g ? '_clock' then clk := jsonb_build_object('left', coalesce((st->>'clk')::integer, (g->>'_clock')::integer), 'total', (g->>'_clock')::integer); end if;
  return jsonb_build_object('run_id', r.id, 'dungeon_no', r.dungeon_no, 'status', r.status, 'leader_id', r.leader_id, 'pow', (st->>'pow')::integer,
    'flags', coalesce((select jsonb_agg(jsonb_build_object('id', f, 'label', coalesce(lbl->>f, f))) from jsonb_array_elements_text(st->'flags') f), '[]'::jsonb),
    'members', coalesce((select jsonb_agg(jsonb_build_object('user_id', x->>'user_id', 'nickname', x->>'nickname', 'role', x->>'role', 'level', (x->>'level')::integer, 'hp', round((x->>'hp')::numeric), 'max_hp', round((x->>'mx')::numeric)))
                         from jsonb_array_elements(st->'members') x), '[]'::jsonb),
    'scene', case when txt is null then null else jsonb_build_object('id', st->>'node', 'type', nd->>'t', 'title', nd->>'n', 'text', txt, 'options', opts, 'lock', lk) end,
    'clock', clk,
    'step', jsonb_array_length(st->'log'), 'log', st->'log',
    'last_move_at', r.last_move_at, 'expires_at', r.last_move_at + make_interval(mins => greatest(1, public._setting('game_dng_path_minutes'))));
end $$;

-- ---------- la storia avanza: la serratura si ferma come una scena ----------
create or replace function public._game_dng_advance(p_state jsonb, p_graph jsonb, p_no integer) returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare d public.game_dungeons%rowtype; st jsonb := p_state; nd jsonb; t text; guard integer := 0; diff numeric; res jsonb; fl text[]; c jsonb; hit text; mem jsonb; x jsonb; y jsonb; j integer;
  w boolean; kind text; hits numeric; apct numeric; rm jsonb; mm jsonb;
begin
  select * into d from public.game_dungeons where no = p_no;
  diff := d.diff * (0.8 + 0.55 * (1 - exp(-(d.ref_level - 1) / 25.0))) * greatest(10, public._setting('game_dng_difficulty')) / 100.0;
  loop
    guard := guard + 1;
    if guard > 40 then raise exception 'Percorso del dungeon non valido'; end if;
    nd := p_graph->(st->>'node');
    if nd is null then raise exception 'Percorso del dungeon non valido'; end if;
    t := nd->>'t';
    if t in ('scene', 'lock') then return jsonb_build_object('state', st, 'end', null); end if;
    if t = 'end' then return jsonb_build_object('state', st, 'end', nd || jsonb_build_object('id', st->>'node')); end if;
    select coalesce(array_agg(f), '{}') into fl from jsonb_array_elements_text(st->'flags') f;
    if t = 'route' then
      hit := nd->>'d';
      for c in select * from jsonb_array_elements(nd->'c') loop
        if coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(c->'if') f), true) then hit := c->>'to'; exit; end if;
      end loop;
      st := jsonb_set(st, '{node}', to_jsonb(hit));
    elsif t = 'fight' then
      kind := coalesce(nd->>'k', 'n');
      hits := case kind when 'b' then 20 when 'e' then 16 else 12 end;
      apct := case kind when 'b' then 0.125 when 'e' then 0.11 else 0.09 end;
      res := public._game_dng_clash(st->'members', jsonb_build_object('m', coalesce((nd->>'m')::numeric, 1), 'hits', hits, 'apct', apct), (st->>'pow')::numeric, diff, d.ref_level);
      w := (res->>'win')::boolean;
      mem := '[]'::jsonb; mm := '[]'::jsonb;
      for j in 0..jsonb_array_length(st->'members') - 1 loop
        x := st->'members'->j; y := res->'members'->j;
        x := x || jsonb_build_object('dealt', (x->>'dealt')::numeric + (y->>'dealt')::numeric, 'taken', (x->>'taken')::numeric + (y->>'taken')::numeric, 'healed', (x->>'healed')::numeric + (y->>'healed')::numeric);
        mm := mm || jsonb_build_array(jsonb_build_object('user_id', x->>'user_id', 'nickname', x->>'nickname', 'role', x->>'role', 'dealt', (y->>'dealt')::numeric, 'taken', (y->>'taken')::numeric,
                                                          'healed', (y->>'healed')::numeric, 'hp', round((y->>'hp')::numeric), 'max_hp', round((x->>'mx')::numeric), 'ko', (y->>'ko')::boolean));
        if w then   -- dopo una vittoria il gruppo si riposa: +25% dei PV massimi (chi era KO torna con il 25%)
          x := jsonb_set(x, '{hp}', to_jsonb(round(case when (y->>'hp')::numeric <= 0 then 0.25 * (x->>'mx')::numeric else least((x->>'mx')::numeric, (y->>'hp')::numeric + 0.25 * (x->>'mx')::numeric) end, 2)));
        else
          x := jsonb_set(x, '{hp}', to_jsonb(round((y->>'hp')::numeric, 2)));
        end if;
        mem := mem || jsonb_build_array(x);
      end loop;
      st := jsonb_set(st, '{members}', mem);
      st := jsonb_set(st, '{rooms}', (st->'rooms') || jsonb_build_array(jsonb_build_object('no', jsonb_array_length(st->'rooms') + 1, 'name', nd->>'e', 'emoji', nd->>'em', 'boss', kind = 'b', 'cleared', w,
                                                                                         'rounds', (res->>'rounds')::integer, 'enemy_hp', (res->>'enemy_hp')::bigint, 'members', mm)));
      st := jsonb_set(st, '{log}', (st->'log') || jsonb_build_array(jsonb_build_object('k', 'f', 'e', nd->>'e', 'em', nd->>'em', 'boss', kind = 'b', 'win', w, 'rounds', (res->>'rounds')::integer)));
      if w then
        st := public._game_dng_fx(st, nd->'wfx');
        st := jsonb_set(st, '{node}', to_jsonb(nd->>'w'));
      else
        st := jsonb_set(st, '{node}', to_jsonb(nd->>'l'));
      end if;
    else
      raise exception 'Percorso del dungeon non valido';
    end if;
  end loop;
end $$;

-- ---------- una scelta del capo gruppo (p_arg: la combinazione «0,3,1» della serratura, oppure l'eroe scelto) ----------
drop function if exists public.game_dungeon_choose(uuid, text);
create or replace function public.game_dungeon_choose(p_run uuid, p_option text, p_arg text default null) returns jsonb language plpgsql security definer set search_path = public as $$
declare v uuid := public._need_role(array['user','organizer','moderator','admin']::public.app_role[]); r public.game_runs%rowtype; g jsonb; st jsonb; nd jsonb; o jsonb; fl text[]; adv jsonb; e jsonb; res jsonb;
  dest text; who_ text; rl text; nick text; okc boolean; pr numeric; rtxt text; cost integer; ck jsonb; lg jsonb; nsym integer; nlen integer; guess integer[]; code integer[]; pos integer; used_n integer; left_ integer;
  lkey text; gl text; byj jsonb;
begin
  perform public._require_module('heroes');
  select * into r from public.game_runs where id = p_run for update;
  if not found or r.status <> 'active' then raise exception 'Questo dungeon non è in corso'; end if;
  if r.last_move_at < now() - make_interval(mins => greatest(1, public._setting('game_dng_path_minutes'))) then
    perform public._game_dng_expire_active();
    return jsonb_build_object('run_id', p_run, 'dungeon_no', r.dungeon_no, 'status', 'failed', 'expired', true);
  end if;
  if r.leader_id <> v then raise exception 'Solo il capo gruppo può scegliere'; end if;
  select graph into g from public.game_dungeon_graphs where dungeon_no = r.dungeon_no;
  st := r.state; nd := g->(st->>'node');
  if nd is null or nd->>'t' not in ('scene', 'lock') then raise exception 'Non c’è nessuna scelta da fare'; end if;
  if g ? '_clock' and not (st ? 'clk') then st := jsonb_set(st, '{clk}', to_jsonb((g->>'_clock')::integer)); end if;
  select coalesce(array_agg(f), '{}') into fl from jsonb_array_elements_text(st->'flags') f;

  if nd->>'t' = 'lock' then
    -- serratura: una combinazione di simboli (indici da 0), tutti diversi
    nsym := jsonb_array_length(nd->'sym'); nlen := jsonb_array_length(nd->'code');
    begin
      guess := string_to_array(btrim(coalesce(p_arg, '')), ',')::integer[];
    exception when others then raise exception 'Combinazione non valida';
    end;
    if guess is null or coalesce(array_length(guess, 1), 0) <> nlen or exists (select 1 from unnest(guess) q where q < 0 or q >= nsym)
       or (select count(distinct q) from unnest(guess) q) <> nlen then
      raise exception 'Combinazione non valida: scegli % simboli, tutti diversi', nlen;
    end if;
    select array_agg((c.v)::integer order by c.ord) into code from jsonb_array_elements_text(nd->'code') with ordinality as c(v, ord);
    lkey := st->>'node';
    used_n := coalesce((st->'lk'->>lkey)::integer, 0);
    if used_n >= (nd->>'tries')::integer then raise exception 'Non ci sono più tentativi'; end if;
    used_n := used_n + 1;
    st := jsonb_set(st, '{lk}', coalesce(st->'lk', '{}'::jsonb) || jsonb_build_object(lkey, used_n));
    select count(*) into pos from generate_subscripts(guess, 1) i where guess[i] = code[i];
    select string_agg(nd->'sym'->>(q.s), ' ' order by q.ord) into gl from unnest(guess) with ordinality as q(s, ord);
    if pos = nlen then
      st := public._game_dng_fx(st, nd->'okfx');
      st := jsonb_set(st, '{log}', (st->'log') || jsonb_build_array(jsonb_build_object('k', 'l', 'n', nd->>'n', 'l', gl, 'ok', true, 'r', coalesce(nd->>'rok', ''))));
      st := jsonb_set(st, '{node}', to_jsonb(nd->>'ok')) - 'lkf';
    else
      st := public._game_dng_fx(st, nd->'kofx');
      left_ := (nd->>'tries')::integer - used_n;
      if left_ <= 0 then
        st := jsonb_set(st, '{log}', (st->'log') || jsonb_build_array(jsonb_build_object('k', 'l', 'n', nd->>'n', 'l', gl, 'ok', false, 'r', coalesce(nd->>'rko', ''))));
        st := jsonb_set(st, '{node}', to_jsonb(nd->>'ko')) - 'lkf';
      else
        st := jsonb_set(st, '{lkf}', to_jsonb(format('%s su %s simboli al posto giusto. Tentativi rimasti: %s.', pos, nlen, left_)));
        st := jsonb_set(st, '{log}', (st->'log') || jsonb_build_array(jsonb_build_object('k', 'l', 'n', nd->>'n', 'l', gl, 'ok', false, 'r', format('%s su %s al posto giusto.', pos, nlen))));
      end if;
    end if;
  else
    select x into o from jsonb_array_elements(nd->'o') x where x->>'id' = p_option;
    if o is null then raise exception 'Scelta non valida'; end if;
    if o ? 'only' and not coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(o->'only') f), true) then raise exception 'Scelta non valida'; end if;
    if o ? 'req' and not coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(o->'req') f), true) then raise exception 'Questa scelta non è ancora disponibile'; end if;
    if o ? 'role' and not exists (select 1 from jsonb_array_elements(st->'members') m where m->>'role' = o->>'role') then raise exception 'Questa scelta non è ancora disponibile'; end if;
    if coalesce((o->>'stay')::boolean, false) and coalesce(st->'used', '[]'::jsonb) @> to_jsonb((st->>'node') || ':' || (o->>'id')) then raise exception 'Hai già fatto questa azione'; end if;
    if coalesce((o->>'who')::boolean, false) then
      select m->>'user_id', m->>'role', m->>'nickname' into who_, rl, nick from jsonb_array_elements(st->'members') m where m->>'user_id' = coalesce(p_arg, '');
      if who_ is null then raise exception 'Scegli quale eroe affronta la prova'; end if;
    end if;
    st := public._game_dng_fx(st, o->'fx');
    if who_ is not null then st := public._game_dng_fx(st, o->'fxw', who_); end if;
    dest := o->>'to'; rtxt := coalesce(o->>'r', ''); lg := '{}'::jsonb;
    if who_ is not null then
      -- l'esito dipende dal ruolo dell'eroe scelto: by.<ruolo> = {to, r, fx (a tutti), fxw (solo a lui)}
      byj := o->'by'->rl;
      if byj is not null then
        st := public._game_dng_fx(st, byj->'fx');
        st := public._game_dng_fx(st, byj->'fxw', who_);
        dest := coalesce(byj->>'to', dest); rtxt := coalesce(byj->>'r', rtxt);
      end if;
      lg := lg || jsonb_build_object('w', nick);
    end if;
    if o ? 'chk' then
      ck := o->'chk';
      pr := public._game_dng_odds(st, ck->>'s', (ck->>'b')::numeric);
      okc := random() < pr;
      st := public._game_dng_fx(st, case when okc then ck->'okfx' else ck->'kofx' end);
      dest := case when okc then ck->>'ok' else ck->>'ko' end;
      rtxt := coalesce(case when okc then ck->>'rok' else ck->>'rko' end, rtxt);
      lg := lg || jsonb_build_object('chk', jsonb_build_object('s', ck->>'s', 'p', round(100 * pr), 'ok', okc));
    end if;
    if coalesce((o->>'stay')::boolean, false) then
      dest := st->>'node';
      st := jsonb_set(st, '{used}', coalesce(st->'used', '[]'::jsonb) || to_jsonb((st->>'node') || ':' || (o->>'id')));
    end if;
    st := jsonb_set(st, '{log}', (st->'log') || jsonb_build_array(jsonb_build_object('k', 'c', 'n', nd->>'n', 'l', o->>'l', 'r', rtxt) || lg));
    st := jsonb_set(st, '{node}', to_jsonb(dest));
    -- orologio: ogni mossa ne consuma una (cost: 0 per non consumarla); a zero il tempo è scaduto
    if st ? 'clk' then
      cost := coalesce((o->>'cost')::integer, 1);
      st := jsonb_set(st, '{clk}', to_jsonb(greatest(0, (st->>'clk')::integer - cost)));
      if (st->>'clk')::integer <= 0 and cost > 0 and g ? '_late' and dest <> g->>'_late' and coalesce(g->dest->>'t', '') <> 'end' then
        st := jsonb_set(st, '{node}', to_jsonb(g->>'_late'));
        st := jsonb_set(st, '{log}', (st->'log') || jsonb_build_array(jsonb_build_object('k', 't', 'r', coalesce(g->>'_latetxt', 'Il tempo è scaduto.'))));
      end if;
    end if;
  end if;

  adv := public._game_dng_advance(st, g, r.dungeon_no::integer);
  st := adv->'state'; e := adv->'end';
  update public.game_runs set state = st, last_move_at = clock_timestamp() where id = p_run;
  if e is not null and e <> 'null'::jsonb then
    res := public._game_dng_settle(p_run, coalesce((e->>'win')::boolean, false), e);
    return jsonb_build_object('run_id', p_run, 'dungeon_no', r.dungeon_no, 'status', case when (res->>'win')::boolean then 'cleared' else 'failed' end, 'result', res);
  end if;
  return jsonb_build_object('run_id', p_run, 'dungeon_no', r.dungeon_no, 'status', 'active', 'view', public._game_dng_view(p_run));
end $$;

-- ---------- stato: ora dichiara anche quali interazioni usa ogni dungeon ----------
create or replace function public.game_dungeon_state() returns jsonb language plpgsql security definer set search_path = public as $$
declare v uuid := public._need_role(array['user','organizer','moderator','admin']::public.app_role[]); b jsonb; act uuid; cleared integer; total integer;
begin
  perform public._require_module('heroes');
  perform public._game_dng_expire_active();
  b := public._game_dng_state_base();
  select m.run_id into act from public.game_run_members m join public.game_runs r on r.id = m.run_id where m.user_id = v and r.status = 'active' order by r.started_at desc limit 1;
  cleared := (b->>'cleared')::integer; total := (b->>'total')::integer;
  b := jsonb_set(b, '{next_epic_in}', to_jsonb(case when cleared >= total then 0 else 5 - (cleared % 5) end));
  b := jsonb_set(b, '{dungeons}', coalesce((select jsonb_agg(e || jsonb_build_object('kind', d.kind,
          'endings_total', coalesce((select count(*) from jsonb_each(gg.graph) x where x.value->>'t' = 'end'), 0),
          'endings_found', (select count(*) from public.game_dungeon_endings en where en.user_id = v and en.dungeon_no = d.no),
          'forks', coalesce((select count(*) from jsonb_each(gg.graph) x where x.value->>'t' in ('scene', 'lock')), 0),
          'inter', coalesce((select jsonb_agg(q.k order by q.o) from (
              select 1 o, 'chk' k where position('"chk":' in gg.graph::text) > 0 union all select 2, 'lock' where position('"t": "lock"' in gg.graph::text) > 0
              union all select 3, 'stay' where position('"stay":' in gg.graph::text) > 0 union all select 4, 'who' where position('"who":' in gg.graph::text) > 0
              union all select 5, 'role' where position('"role":' in gg.graph::text) > 0 union all select 6, 'clock' where position('"_clock":' in gg.graph::text) > 0 order by 1) q), '[]'::jsonb)) order by d.no)
        from jsonb_array_elements(b->'dungeons') e join public.game_dungeons d on d.no = (e->>'no')::smallint left join public.game_dungeon_graphs gg on gg.dungeon_no = d.no), '[]'::jsonb));
  return b || jsonb_build_object('active', case when act is null then null else public._game_dng_view(act) end, 'path_minutes', public._setting('game_dng_path_minutes'));
end $$;

-- ---------- permessi ----------
revoke all on function public._game_dng_fx(jsonb, jsonb, text), public._game_dng_odds(jsonb, text, numeric), public._game_dng_view(uuid), public._game_dng_advance(jsonb, jsonb, integer) from public, anon, authenticated;
revoke all on function public.game_dungeon_choose(uuid, text, text), public.game_dungeon_state() from public, anon;
grant execute on function public.game_dungeon_choose(uuid, text, text), public.game_dungeon_state() to authenticated;


-- =====================================================================
-- PARTE 2 — dungeon 56–100 (ex 028)
-- =====================================================================

do $$
begin
  if to_regprocedure('public._game_dng_odds(jsonb,text,numeric)') is null then
    raise exception 'Esegui prima la migrazione 027 (black-market-eroi-dungeon-interazioni.sql): questi dungeon usano le nuove interazioni';
  end if;
  if (select count(*) from public.game_dungeons where no between 1 and 55) <> 55 then
    raise exception 'Mancano i dungeon 1–55: esegui prima le migrazioni precedenti';
  end if;
end $$;

