 (81, $j${"_start":"s1","f1":{"t":"fight","e":"Sassi Meditanti","em":"🪨","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Il viale dei sassi","x":"Un viale di sassi bianchi taglia il giardino. I sassi si girano a guardare chi passa: uno solo di voi può camminare in testa al gruppo senza lasciare impronte sulla sabbia.","o":[{"id":"a","l":"Scegliere chi apre la marcia sul viale","who":true,"to":"f1","by":{"tank":{"r":"Il Tank avanza pesante: lascia impronte profonde e i sassi, offesi, rotolano addosso al gruppo.","fx":{"pow":-5},"fxw":{"hp":-40}},"dps":{"r":"L’eroe Danni cammina rapido ma i suoi passi sono nervosi, e il viale si increspa.","fxw":{"hp":-20}},"support":{"r":"Il Supporto avanza lieve come una brezza: la sabbia non registra nulla.","fx":{"pow":12},"fxw":{"hp":-5}}}},{"id":"b","l":"Attraversare il viale tutti in fila, passo dopo passo","r":"La sabbia si increspa un poco, ma il gruppo passa.","to":"f1","fx":{"hp":-20}}]},"f2":{"t":"fight","e":"Monaci di Sabbia","em":"🏜️","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"Il padiglione del tè","x":"Nel padiglione, un monaco di sabbia versa il tè senza fermarsi. Per passare occorre non spezzare la sua cerimonia. Sul tavolino ci sono tre fogli: uno è un indizio sul portale del giardino.","o":[{"id":"a","l":"Il Tank siede immobile al tavolo e sostiene il peso della cerimonia","r":"Il monaco continua a versare: apprezza la calma. Leggete l’indizio sul foglio.","role":"tank","to":"f2","fx":{"pow":12,"hp":-10}},{"id":"b","l":"Un eroe Danni disarma i rastrelli danzanti che girano attorno al padiglione","r":"I rastrelli cadono senza rumore e il foglio dell’indizio è vostro.","role":"dps","to":"f2","fx":{"pow":15,"hp":-15}},{"id":"c","l":"Il Supporto serve il tè al monaco con inchino","r":"Il monaco sorride, e vi mostra un foglio con l’indizio del portale.","role":"support","to":"f2","fx":{"flag":"indizio","hp":15}},{"id":"d","l":"Meditare insieme al monaco fino a vedere la sequenza","chk":{"s":"spi","b":40,"ok":"f2","ko":"f2","okfx":{"flag":"indizio"},"kofx":{"hp":-20},"rok":"Nella quiete la sequenza dei sassi vi appare chiara.","rko":"Il vostro pensiero vaga e il monaco si volta, deluso."}},{"id":"z","l":"Rovesciare la teiera del monaco","to":"eF2"}]},"f3":{"t":"fight","e":"Rastrelli Danzanti","em":"🧹","m":1.2,"k":"e","w":"fin","l":"eDef"},"fk3":{"t":"fight","e":"Rastrelli Danzanti (allarme)","em":"🧹","m":1.3,"k":"e","w":"f3","l":"eDef"},"s3":{"t":"lock","n":"Il portale dei cinque sassi","x":"Cinque sassi di forme diverse chiudono il portale: tre vanno toccati nell’ordine del rastrellamento.","sym":["🌊","🌸","🌙","⛰️","🍃"],"code":[0,1,2],"tries":3,"ok":"f3","ko":"fk3","okfx":{"flag":"key","pow":8},"kofx":{"hp":-10},"rok":"Il portale si apre in silenzio e la Pietra del Silenzio vi si posa in mano, leggera come un respiro.","rko":"I sassi sbagliati rotolano via e il giardino si richiude con un sospiro di rimprovero.","h":{"if":"indizio","t":"Il foglio del monaco elenca la sequenza: «onda», poi «fiore», poi «luna»."}},"fin":{"t":"scene","n":"Il cerchio di sabbia","x":"Al centro del giardino, il Maestro del Rastrello Rotto sta fermo davanti a un cerchio di sabbia perfetta. Manca un solo sasso al centro.","o":[{"id":"a","l":"Posare la Pietra del Silenzio al centro del cerchio","r":"La sabbia si ferma e il Maestro, per la prima volta, resta senza gesti da fare.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Maestro del Rastrello Rotto ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Maestro del Rastrello Rotto a viso aperto","r":"Maestro del Rastrello Rotto si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Rastrellare una linea nel cerchio","to":"eFa","cost":0},{"id":"e","l":"Spezzare il rastrello del Maestro","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Maestro del Rastrello Rotto","em":"🧘","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il giardino ricomposto","x":"La Pietra del Silenzio ferma ogni sabbia: il Maestro appoggia il rastrello e il giardino, intatto, vi lascia andare con un inchino.","text":"La Pietra del Silenzio ferma ogni sabbia: il Maestro appoggia il rastrello e il giardino, intatto, vi lascia andare con un inchino.","m":140},"eGood":{"t":"end","win":true,"title":"Il rastrello cade","x":"Il Maestro cade con il rastrello in mano e la sabbia si disperde. Il giardino respira, finalmente.","text":"Il Maestro cade con il rastrello in mano e la sabbia si disperde. Il giardino respira, finalmente.","m":115},"eOk":{"t":"end","win":true,"title":"Una linea spezzata","x":"Il Maestro si ritira nel padiglione. Uscite con la sabbia nelle scarpe e il fiato corto.","text":"Il Maestro si ritira nel padiglione. Uscite con la sabbia nelle scarpe e il fiato corto.","m":85},"eF2":{"t":"end","win":false,"title":"Una trappola mortale","x":"La cerimonia si spezza e il monaco rastrella voi, fino all’ultimo granello.","text":"La cerimonia si spezza e il monaco rastrella voi, fino all’ultimo granello.","m":100},"eFa":{"t":"end","win":false,"title":"Un passo falso","x":"Il Maestro vi guarda: la linea è l’ultima cosa che voi tracciate.","text":"Il Maestro vi guarda: la linea è l’ultima cosa che voi tracciate.","m":100},"eFb":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il Maestro non ha mai avuto altro che quel rastrello.","text":"Il Maestro non ha mai avuto altro che quel rastrello.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Maestro del Rastrello Rotto vi cancella dalla sabbia: la spedizione è fallita.","text":"Il Maestro del Rastrello Rotto vi cancella dalla sabbia: la spedizione è fallita.","m":100},"_flags":{"key":"Pietra del Silenzio","sigillo":"Colpo decisivo","indizio":"Indizio"}}$j$::json