 (82, $j${"_start":"s1","_clock":7,"_late":"fL","_latetxt":"Il corno suona l’ultima volta e il vulcano erutta: la lava vi raggiunge prima che possiate fare altro.","f1":{"t":"fight","e":"Salamandre di Magma","em":"🦎","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Il fianco del vulcano","x":"Il fianco del vulcano trema a ogni respiro. Ogni scelta che fate costa tempo: il corno dell’Araldo suona sempre più vicino e la roccia si arrossa.","o":[{"id":"a","l":"Correre lungo il sentiero di pietra fredda","r":"Il sentiero regge e vi porta più in alto, ma il fiato è corto.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Bere dalla sorgente tiepida in una fenditura","r":"L’acqua è tiepida e buona: vi rimette in forze.","stay":true,"fx":{"hp":25}},{"id":"c","l":"Studiare i tremori per prevedere le eruzioni","r":"Imparate il ritmo del vulcano: sapete dove mettere i piedi.","stay":true,"fx":{"pow":10}},{"id":"d","l":"Spaccare un blocco di ossidiana per farne una lama","r":"La lama è affilata come un vetro nero: vi dà forza.","stay":true,"fx":{"pow":15,"hp":-20}},{"id":"e","l":"Raccogliere polvere di zolfo per accecare i nemici","r":"La polvere vi dà un vantaggio, se non inciampate.","stay":true,"fx":{"pow":5,"hp":10}},{"id":"x","l":"Puntare dritti al camino dell’Araldo","r":"Il camino si apre e vi trascina verso l’alto.","to":"f1"},{"id":"z","l":"Calarsi nel cratere per accorciare la strada","to":"eF1"}]},"f2":{"t":"fight","e":"Corni Infuocati","em":"📯","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"Il ponte di lava","x":"Un ponte di roccia attraversa un fiume di lava. Solo uno di voi può camminare in testa e sorreggere il gruppo mentre il ponte si spezza ad ogni passo.","o":[{"id":"a","l":"Scegliere chi guida il gruppo sul ponte di lava","who":true,"to":"f2","by":{"tank":{"r":"Il Tank regge il ponte con la schiena: la lava lo lambisce, ma il gruppo passa.","fx":{"pow":12},"fxw":{"hp":-5}},"dps":{"r":"L’eroe Danni corre sul ponte, ma una crepa lo coglie in pieno.","fxw":{"hp":-20}},"support":{"r":"Il Supporto avanza esitante: il ponte cede e deve essere curato in fretta.","fx":{"pow":-5},"fxw":{"hp":-40}}}},{"id":"b","l":"Attraversare il ponte uno alla volta","r":"Il ponte regge a stento: tutti passano, anche se un po’ bruciacchiati.","to":"f2","fx":{"hp":-20}}]},"f3":{"t":"fight","e":"Bombe Vulcaniche","em":"💣","m":1.2,"k":"e","w":"fin","l":"eDef"},"s3":{"t":"scene","n":"Il camino dell’Araldo","x":"Il camino dell’Araldo sale ripido, fumante. Quattro modi di salire: ognuno mette alla prova una dote.","o":[{"id":"a","l":"Arrampicarsi a forza di braccia sulle pareti roventi","chk":{"s":"for","b":70,"ok":"f3","ko":"f3","okfx":{"flag":"key","pow":8},"kofx":{"hp":-15,"pow":-5},"rok":"Le pareti scottano ma voi salite: il Corno di Cenere vi attende sul bordo.","rko":"Le mani vi scivolano e vi bruciate."}},{"id":"b","l":"Saltare di sporgenza in sporgenza","chk":{"s":"des","b":50,"ok":"f3","ko":"f3","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Vi muovete come una salamandra: nessuna scottatura.","rko":"Sbagliate il momento: pagate un prezzo in forze."}},{"id":"c","l":"Resistere al calore salendo piano","chk":{"s":"vig","b":50,"ok":"f3","ko":"f3","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Il calore vi mette alla prova e voi resistete.","rko":"Non basta: serve un piano migliore, e intanto si soffre."}},{"id":"d","l":"Invocare un vento fresco con una preghiera","chk":{"s":"spi","b":50,"ok":"f3","ko":"f3","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Un soffio d’aria vi accompagna in cima.","rko":"Non va come speravate: vi costa fatica."}},{"id":"z","l":"Tuffarsi nel camino per farla finita in fretta","to":"eF3"}]},"fL":{"t":"fight","e":"Fiumi di Lava","em":"🌋","m":1.5,"k":"e","w":"fin","l":"eDef"},"fin":{"t":"scene","n":"La bocca del vulcano","x":"L’Araldo di Fuoco sta sul bordo della bocca, il corno alle labbra. Sotto di lui, il magma ribolle impaziente.","o":[{"id":"a","l":"Soffiare nel Corno di Cenere in risposta all’Araldo","r":"Il corno suona una nota che spegne il fuoco: l’Araldo rimane senza fiato.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Araldo di Fuoco ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Araldo di Fuoco a viso aperto","r":"Araldo di Fuoco si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Offrire il vostro fiato all’Araldo","to":"eFa","cost":0},{"id":"e","l":"Strappargli il corno dalle labbra","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Araldo di Fuoco","em":"📯","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"L’eruzione spenta","x":"Il Corno di Cenere soffoca l’ultima eruzione: l’Araldo, vuoto di fuoco, si siede sul bordo e il vulcano si addormenta.","text":"Il Corno di Cenere soffoca l’ultima eruzione: l’Araldo, vuoto di fuoco, si siede sul bordo e il vulcano si addormenta.","m":140},"eGood":{"t":"end","win":true,"title":"L’Araldo tace","x":"L’Araldo cade nel cratere e il corno tace. Il vulcano brontola, ma non esplode.","text":"L’Araldo cade nel cratere e il corno tace. Il vulcano brontola, ma non esplode.","m":115},"eOk":{"t":"end","win":true,"title":"Una nota corta","x":"L’Araldo si ritira nel fumo. Scendete dal vulcano con la pelle arrossata e un fischio nelle orecchie.","text":"L’Araldo si ritira nel fumo. Scendete dal vulcano con la pelle arrossata e un fischio nelle orecchie.","m":85},"eF1":{"t":"end","win":false,"title":"Una trappola mortale","x":"Il cratere è più caldo di quanto sembrasse.","text":"Il cratere è più caldo di quanto sembrasse.","m":100},"eF3":{"t":"end","win":false,"title":"Un passo falso","x":"Il fondo del camino è lava, e non è più fresca di prima.","text":"Il fondo del camino è lava, e non è più fresca di prima.","m":100},"eFa":{"t":"end","win":false,"title":"Una scelta fatale","x":"L’Araldo lo prende tutto.","text":"L’Araldo lo prende tutto.","m":100},"eFb":{"t":"end","win":false,"title":"L’ultimo errore","x":"L’Araldo lo suona un’ultima volta: il vulcano risponde.","text":"L’Araldo lo suona un’ultima volta: il vulcano risponde.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"L’Araldo di Fuoco suona la fine: la spedizione è fallita.","text":"L’Araldo di Fuoco suona la fine: la spedizione è fallita.","m":100},"_flags":{"key":"Corno di Cenere","sigillo":"Colpo decisivo"}}$j$::jsonb),
 (83, $j${"_start":"s1","f1":{"t":"fight","e":"Ingranaggi Impazziti","em":"⚙️","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"La piazza dei carillon","x":"In piazza suonano mille carillon sfasati. Tre cose bloccano la strada: un portone pesante, un meccanismo da ingrippare e una melodia da mettere in ordine.","o":[{"id":"a","l":"Il Tank spinge il portone dei carillon con le spalle","r":"Il portone cede con un lamento e la strada si apre.","role":"tank","to":"f1","fx":{"pow":12,"hp":-10}},{"id":"b","l":"Un eroe Danni sfascia il meccanismo che regola i carillon","r":"Il meccanismo salta in mille pezzi e il baccano si placa.","role":"dps","to":"f1","fx":{"pow":15,"hp":-15}},{"id":"c","l":"Il Supporto fischietta la melodia giusta","r":"I carillon si accordano, uno a uno, sulla melodia.","role":"support","to":"f1","fx":{"pow":10,"hp":15}},{"id":"d","l":"Zigzagare tra i pendoli oscillanti","chk":{"s":"des","b":40,"ok":"f1","ko":"f1","okfx":{"pow":8},"kofx":{"hp":-20},"rok":"Passate fra i pendoli senza un graffio.","rko":"Un pendolo vi colpisce in pieno."}},{"id":"z","l":"Fermare i pendoli con le mani nude","to":"eF1"}]},"f2":{"t":"fight","e":"Cuculi Meccanici","em":"🐦","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"L’officina del Maestro","x":"L’officina è piena di orologi smontati. Un banco con una lente, una cassa di pezzi di ricambio, una brandina; su una mensola riposa la Chiave del Mezzogiorno.","o":[{"id":"a","l":"Riposare un attimo sulla brandina del Maestro","r":"Dormire con il ticchettio vi fa bene: vi alzate più riposati.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Ricostruire un orologio con i pezzi di ricambio","r":"L’orologio ticchetta: la sua precisione vi incoraggia.","stay":true,"fx":{"hp":25}},{"id":"c","l":"Leggere gli appunti del Maestro sul banco","r":"Gli appunti elencano i simboli della chiave: «Il mezzogiorno è l’ora di sole, luna e ingranaggio». Prendete nota.","stay":true,"fx":{"flag":"indizio"}},{"id":"x","l":"Lasciare la stanza e proseguire","r":"Vi lasciate la sala alle spalle e scendete più a fondo.","to":"f2"},{"id":"z","l":"Smontare l’orologio più grande della stanza","to":"eF2"}]},"f3":{"t":"fight","e":"Lancette Taglienti","em":"🗡️","m":1.2,"k":"e","w":"fin","l":"eDef"},"fk3":{"t":"fight","e":"Lancette Taglienti (allarme)","em":"🗡️","m":1.3,"k":"e","w":"f3","l":"eDef"},"s3":{"t":"lock","n":"La cassaforte del tempo","x":"La cassaforte del Maestro ha cinque quadranti: tre vanno puntati nell’ordine giusto per aprire lo scomparto della Chiave.","sym":["☀️","🌙","⚙️","⏳","🔔"],"code":[1,4,2],"tries":3,"ok":"f3","ko":"fk3","okfx":{"flag":"key","pow":8},"kofx":{"hp":-10},"rok":"La cassaforte si apre con uno scatto: la Chiave del Mezzogiorno vi cade in mano, ancora calda.","rko":"I quadranti sbagliati scattano all’indietro e la cassaforte si stringe.","h":{"if":"indizio","t":"Gli appunti del Maestro dicono: «luna», poi «campana», poi «ingranaggio»."}},"fin":{"t":"scene","n":"Il grande orologio","x":"Il Maestro Orologiaio ripara l’orologio più grande della città, lo stesso da mille anni. Una sola fessura aspetta una chiave.","o":[{"id":"a","l":"Inserire la Chiave del Mezzogiorno nell’orologio","r":"L’orologio scatta sul mezzogiorno: il Maestro si ferma, sorpreso dal proprio tempo.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Maestro Orologiaio ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Maestro Orologiaio a viso aperto","r":"Maestro Orologiaio si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Chiedere al Maestro che ore sono","to":"eFa","cost":0},{"id":"e","l":"Spingere indietro le lancette","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Maestro Orologiaio","em":"⚙️","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il mezzogiorno finalmente","x":"La Chiave del Mezzogiorno fa scattare l’ora giusta: il Maestro Orologiaio sorride, gli orologi si fermano uno ad uno e la città, finalmente, dorme.","text":"La Chiave del Mezzogiorno fa scattare l’ora giusta: il Maestro Orologiaio sorride, gli orologi si fermano uno ad uno e la città, finalmente, dorme.","m":140},"eGood":{"t":"end","win":true,"title":"Il tempo si ferma","x":"Il Maestro cade tra gli ingranaggi. L’orologio più grande tace e la città tira un lungo respiro.","text":"Il Maestro cade tra gli ingranaggi. L’orologio più grande tace e la città tira un lungo respiro.","m":115},"eOk":{"t":"end","win":true,"title":"Un ritardo tollerabile","x":"Il Maestro si ritira nell’officina. Uscite con la sensazione di aver perso qualche minuto.","text":"Il Maestro si ritira nell’officina. Uscite con la sensazione di aver perso qualche minuto.","m":85},"eF1":{"t":"end","win":false,"title":"Un errore di troppo","x":"I pendoli, fermati di colpo, vi stritolano.","text":"I pendoli, fermati di colpo, vi stritolano.","m":100},"eF2":{"t":"end","win":false,"title":"Un passo falso","x":"L’orologio più grande è il cuore della città: smontarlo l’ha svegliato.","text":"L’orologio più grande è il cuore della città: smontarlo l’ha svegliato.","m":100},"eFa":{"t":"end","win":false,"title":"L’ultimo errore","x":"Il Maestro vi risponde con un’ora che non finisce mai.","text":"Il Maestro vi risponde con un’ora che non finisce mai.","m":100},"eFb":{"t":"end","win":false,"title":"Troppa fretta","x":"Il tempo, spinto indietro, vi investe.","text":"Il tempo, spinto indietro, vi investe.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Maestro Orologiaio vi smonta pezzo per pezzo: la spedizione è fallita.","text":"Il Maestro Orologiaio vi smonta pezzo per pezzo: la spedizione è fallita.","m":100},"_flags":{"key":"Chiave del Mezzogiorno","sigillo":"Colpo decisivo","indizio":"Indizio"}}$j$::jsonb),
 (84, $j${"_start":"s1","f1":{"t":"fight","e":"Marionette Scucite","em":"🪆","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Il palcoscenico","x":"Il palcoscenico è pieno di botole e di fili tagliati. La commedia vuole che qualcuno salga sul palco: quattro modi di farlo senza cadere nelle botole.","o":[{"id":"a","l":"Camminare in punta di piedi lungo i bordi del palco","chk":{"s":"des","b":70,"ok":"f1","ko":"f1","okfx":{"pow":12},"kofx":{"hp":-15,"pow":-5},"rok":"Le assi tacciono sotto i vostri passi: nessuna botola vi nota.","rko":"Una botola si apre sotto di voi."}},{"id":"b","l":"Sfondare le botole con un colpo di spalla","chk":{"s":"for","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Le botole saltano e il palco è libero.","rko":"Non va come speravate: vi costa fatica."}},{"id":"c","l":"Recitare la battuta giusta con voce ferma","chk":{"s":"spi","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Le marionette applaudono e vi lasciano passare.","rko":"Qualcosa va storto e il gruppo ne esce ammaccato."}},{"id":"d","l":"Reggere l’imbarazzo di una scena improvvisata","chk":{"s":"vig","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Vi tenete in piedi anche se la scena non finisce mai.","rko":"Il tentativo fallisce e lascia il segno."}},{"id":"z","l":"Chiamare il Burattinaio a gran voce","to":"eF1"}]},"f2":{"t":"fight","e":"Attori di Cartapesta","em":"🎭","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"Il camerino","x":"Nel camerino, una marionetta gigante regge un filo d’argento. Soltanto uno dei vostri può convincerla a darvelo, recitando la parte del burattinaio che non c’è più.","o":[{"id":"a","l":"Scegliere chi recita la parte del burattinaio","who":true,"to":"f2","by":{"tank":{"r":"Il Tank recita con voce pesante: la marionetta si spaventa e se ne va senza filo.","fx":{"pow":-5},"fxw":{"hp":-40}},"dps":{"r":"L’eroe Danni indossa il cappello del burattinaio e dà ordini con tale sicurezza che la marionetta gli cede il filo.","fx":{"pow":12},"fxw":{"hp":-5}},"support":{"r":"Il Supporto balbetta: la marionetta si offende e gli getta in faccia la sua parrucca.","fxw":{"hp":-20}}}},{"id":"b","l":"Recitare la parte tutti insieme come in un coro","r":"La marionetta ride e vi allunga il filo con un’aria di sufficienza.","to":"f2","fx":{"hp":-20}}]},"f3":{"t":"fight","e":"Sipari Strangolatori","em":"🎪","m":1.2,"k":"e","w":"fin","l":"eDef"},"s3":{"t":"scene","n":"Il retropalco","x":"Dietro il sipario, tre argani sorvegliano il Filo d’Argento: uno soffoca, uno taglia, uno incanta. Ognuno si presta a un ruolo diverso.","o":[{"id":"a","l":"Il Tank regge il sipario che cala mentre gli altri passano","r":"Il sipario si ferma sulle sue spalle e il gruppo passa.","role":"tank","to":"f3","fx":{"pow":12,"hp":-10}},{"id":"b","l":"Un eroe Danni taglia le corde dell’argano più nervoso","r":"Le corde si spezzano con un suono secco e l’argano tace.","role":"dps","to":"f3","fx":{"pow":15,"hp":-15}},{"id":"c","l":"Il Supporto intona la ninna nanna dei burattini","r":"Gli argani si addormentano uno ad uno e il Filo d’Argento cala dolcemente.","role":"support","to":"f3","fx":{"flag":"key","hp":15}},{"id":"d","l":"Resistere alle corde che cercano di vostra pelle","chk":{"s":"frt","b":40,"ok":"f3","ko":"f3","okfx":{"flag":"key"},"kofx":{"hp":-20},"rok":"Le corde vi stringono, ma non cedete: il Filo d’Argento è vostro.","rko":"Le corde vi stringono fino a togliervi il fiato."}},{"id":"z","l":"Strappare via il Filo d’Argento dal gancio","to":"eF3"}]},"fin":{"t":"scene","n":"Il boccascena","x":"Il Burattinaio Senza Fili vi osserva dal boccascena, le mani vuote. Davanti a lui, un burattino senza fili aspetta di essere mosso.","o":[{"id":"a","l":"Legare il Filo d’Argento al burattino del Burattinaio","r":"Il burattino si anima da solo e il Burattinaio, per un attimo, non ha più nulla da governare.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Burattinaio Senza Fili ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Burattinaio Senza Fili a viso aperto","r":"Burattinaio Senza Fili si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Applaudire lo spettacolo del Burattinaio","to":"eFa","cost":0},{"id":"e","l":"Cercare di tagliare il burattino","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Burattinaio Senza Fili","em":"🪆","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il sipario cala","x":"Il Filo d’Argento dà vita al burattino: il Burattinaio, senza più nulla da governare, si inchina e il sipario cala sul reame.","text":"Il Filo d’Argento dà vita al burattino: il Burattinaio, senza più nulla da governare, si inchina e il sipario cala sul reame.","m":140},"eGood":{"t":"end","win":true,"title":"Lo spettacolo finisce","x":"Il Burattinaio cade e i burattini si afflosciano uno ad uno. Il teatro è vuoto.","text":"Il Burattinaio cade e i burattini si afflosciano uno ad uno. Il teatro è vuoto.","m":115},"eOk":{"t":"end","win":true,"title":"Un applauso a metà","x":"Il Burattinaio si ritira dietro le quinte. Uscite con una battuta che non ricordate e un filo attaccato al polso.","text":"Il Burattinaio si ritira dietro le quinte. Uscite con una battuta che non ricordate e un filo attaccato al polso.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il Burattinaio vi sente. E vi applaude, con mani fatte di fili.","text":"Il Burattinaio vi sente. E vi applaude, con mani fatte di fili.","m":100},"eF3":{"t":"end","win":false,"title":"L’ultimo errore","x":"Il Filo d’Argento è collegato al sipario, che vi cade addosso.","text":"Il Filo d’Argento è collegato al sipario, che vi cade addosso.","m":100},"eFa":{"t":"end","win":false,"title":"Troppa fretta","x":"L’applauso gli dà i suoi fili: sono i vostri.","text":"L’applauso gli dà i suoi fili: sono i vostri.","m":100},"eFb":{"t":"end","win":false,"title":"Una trappola mortale","x":"Il Burattinaio non perdona chi taglia i suoi fili.","text":"Il Burattinaio non perdona chi taglia i suoi fili.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Burattinaio Senza Fili vi appende al suo sipario: la spedizione è fallita.","text":"Il Burattinaio Senza Fili vi appende al suo sipario: la spedizione è fallita.","m":100},"_flags":{"key":"Filo d’Argento","sigillo":"Colpo decisivo"}}$j$::jsonb),
 (85, $j${"_start":"s1","f1":{"t":"fight","e":"Gocce Vigili","em":"💧","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Il portico dell’acqua","x":"Il portico è sospeso su un lago di vetro: ogni passo produce cerchi nell’acqua. Ci sono una fontana, un altare di perle e un gong; sul fondo una porta di specchi.","o":[{"id":"a","l":"Bere alla fontana dei pellegrini","r":"L’acqua è limpida: vi ristora.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Sedersi a meditare sui cerchi nell’acqua","r":"I cerchi si dispongono in una sequenza che si fissa nella mente.","stay":true,"fx":{"hp":25}},{"id":"c","l":"Osservare i cerchi nell’acqua e prendere nota dell’ordine","r":"I cerchi lasciano vedere dei simboli: «Prima la luna, poi l’onda, in fine il loto». Prendete nota.","stay":true,"fx":{"pow":10}},{"id":"x","l":"Basta così: andare avanti","r":"Il gruppo si ricompone e avanza.","to":"f1"},{"id":"z","l":"Suonare il gong dell’altare","to":"eF1"}]},"f2":{"t":"fight","e":"Riflessi Armati","em":"🪞","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"La sala dei riflessi","x":"La sala è un labirinto di specchi: i vostri riflessi vi osservano. Uno solo di voi può guardare il proprio riflesso negli occhi senza vacillare e guidare il gruppo.","o":[{"id":"a","l":"Scegliere chi guida il gruppo fra i riflessi","who":true,"to":"f2","by":{"tank":{"r":"Il Tank affronta il proprio riflesso a viso aperto: uno scontro sfiancante che lo lascia ammaccato.","fxw":{"hp":-20}},"dps":{"r":"L’eroe Danni colpisce lo specchio: il riflesso ride, e i frammenti lo feriscono.","fx":{"pow":-5},"fxw":{"hp":-40}},"support":{"r":"Il Supporto sostiene lo sguardo del proprio riflesso e lo sorride: lo specchio si addolcisce e vi lascia passare.","fx":{"flag":"indizio","pow":8},"fxw":{"hp":-5}}}},{"id":"b","l":"Chiudere gli occhi e attraversare tenendosi per mano","r":"Non vedete nulla, ma non ci si perde.","to":"f2","fx":{"hp":-20}}]},"f3":{"t":"fight","e":"Pesci di Vetro","em":"🐟","m":1.2,"k":"e","w