 mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Aquila Tonante a viso aperto","r":"Aquila Tonante si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Sfidare l’Aquila a un volo","to":"eFa","cost":0},{"id":"e","l":"Strappare una penna dalla sua ala","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Aquila Tonante","em":"⚡","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il cielo sereno","x":"La Piuma del Tuono riporta l’Aquila alla sua forma: i fulmini si dissolvono, il nido si fa tranquillo e il cielo, sopra di voi, è sereno.","text":"La Piuma del Tuono riporta l’Aquila alla sua forma: i fulmini si dissolvono, il nido si fa tranquillo e il cielo, sopra di voi, è sereno.","m":140},"eGood":{"t":"end","win":true,"title":"Il tuono tace","x":"L’Aquila cade fra i rami del nido e i fulmini si spengono con un ultimo scoppio.","text":"L’Aquila cade fra i rami del nido e i fulmini si spengono con un ultimo scoppio.","m":115},"eOk":{"t":"end","win":true,"title":"Una scarica residua","x":"L’Aquila si ritira fra le nuvole. Uscite col pelo dritto e un ronzio nelle ossa.","text":"L’Aquila si ritira fra le nuvole. Uscite col pelo dritto e un ronzio nelle ossa.","m":85},"eF1":{"t":"end","win":false,"title":"L’ultimo errore","x":"I falchi vi sentono. Tutti.","text":"I falchi vi sentono. Tutti.","m":100},"eF2":{"t":"end","win":false,"title":"Troppa fretta","x":"Il fulmine è molto più reale di quanto sembrasse.","text":"Il fulmine è molto più reale di quanto sembrasse.","m":100},"eF3":{"t":"end","win":false,"title":"Una trappola mortale","x":"L’Aquila sente il rumore, e non è contenta.","text":"L’Aquila sente il rumore, e non è contenta.","m":100},"eFa":{"t":"end","win":false,"title":"Un errore di troppo","x":"L’Aquila vola molto più in alto di voi.","text":"L’Aquila vola molto più in alto di voi.","m":100},"eFb":{"t":"end"