:100},"eFb":{"t":"end","win":false,"title":"L’ultimo errore","x":"La Navigatrice perde la rotta e la sua rabbia.","text":"La Navigatrice perde la rotta e la sua rabbia.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"La Navigatrice delle Dune vi lascia nel deserto: la spedizione è fallita.","text":"La Navigatrice delle Dune vi lascia nel deserto: la spedizione è fallita.","m":100},"_flags":{"key":"Astrolabio d’Argento","sigillo":"Colpo decisivo"}}$j$::jsonb),
 (89, $j${"_start":"s1","f1":{"t":"fight","e":"Frammenti di Sogno","em":"💭","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"La galleria degli specchi rotti","x":"Una galleria di specchi rotti: ogni frammento mostra un sogno diverso. Per attraversarla serve tenere la mente salda. Quattro modi di farlo.","o":[{"id":"a","l":"Guardare i sogni infranti senza lasciarsi catturare","chk":{"s":"spi","b":70,"ok":"f1","ko":"f1","okfx":{"pow":12},"kofx":{"hp":-15,"pow":-5},"rok":"I frammenti vi mostrano ciò che hanno perso e voi ne uscite più saldi.","rko":"Un frammento vi cattura per un attimo e vi riporta a una vecchia ferita."}},{"id":"b","l":"Camminare con gli occhi chiusi sulle schegge","chk":{"s":"frt","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Le schegge vi graffiano appena: passate.","rko":"Non va come speravate: vi costa fatica."}},{"id":"c","l":"Saltare tra i frammenti senza toccarne nessuno","chk":{"s":"des","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Vi muovete come in un balletto: nessuna scheggia vi tocca.","rko":"Qualcosa va storto e il gruppo ne esce ammaccato."}},{"id":"d","l":"Sopportare il ricordo che ogni frammento evoca","chk":{"s":"vig","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Il ricordo pesa, ma lo reggete.","rko":"Il tentativo fallisce e lascia il segno."}},{"id":"z","l":"Spezzare tutti i frammenti per riavere i sogni","to":"eF1"}]},"f2":{"t":"fight","e":"Cavalieri Sonnambuli","em":"🛌","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"La sala del trono vuoto","x":"Una sala immensa con un trono di cuscini, un tappeto di piume, un caminetto spento e un baldacchino. Ognuno suggerisce qualcosa di diverso.","o":[{"id":"a","l":"Riposare un attimo sul tappeto di piume","r":"Le piume sono morbide: vi svegliate più riposati.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Bere una tisana dal servizio d’argento","r":"La tisana è tiepida e buona: ritrovate le forze.","stay":true,"fx":{"hp":25}},{"id":"c","l":"Rovistare fra i cuscini del trono","r":"Fra i cuscini c’è un frammento di sogno che vi dà coraggio.","stay":true,"fx":{"pow":10}},{"id":"x","l":"Voltare pagina: proseguire","r":"Chiudete questa parentesi e andate avanti.","to":"f2"},{"id":"z","l":"Sedersi sul trono vuoto","to":"eF2"}]},"f3":{"t":"fight","e":"Cortigiani d’Ombra","em":"🎭","m":1.2,"k":"e","w":"fin","l":"eDef"},"s3":{"t":"scene","n":"La camera dei desideri","x":"Nella camera dei desideri, un baldacchino custodisce il Cuscino dei Sogni. Per prenderlo, uno di voi deve riaccendere un sogno che non ha mai fatto. Solo chi ha pazienza ci riesce.","o":[{"id":"a","l":"Scegliere chi riaccende il sogno","who":true,"to":"f3","by":{"tank":{"r":"Il Tank sogna una battaglia: il sogno è rumoroso e lo lascia ammaccato, ma il Cuscino non risponde.","fxw":{"hp":-20}},"dps":{"r":"L’eroe Danni sogna la vittoria: troppo in fretta, e il sogno si frantuma.","fx":{"pow":-5},"fxw":{"hp":-40}},"support":{"r":"Il Supporto sogna con calma una stanza silenziosa: il Cuscino dei Sogni lo riconosce e si lascia prendere.","fx":{"flag":"key","pow":8},"fxw":{"hp":-5}}}},{"id":"b","l":"Sognare tutti insieme lo stesso sogno","r":"Il sogno è confuso, ma il Cuscino si lascia prendere, un po’ sgualcito.","to":"f3","fx":{"hp":-20}}]},"fin":{"t":"scene","n":"Il baldacchino della Regina","x":"La Regina degli Incubi è distesa sul suo baldacchino, la corona di sogni storta. Dorme con gli occhi aperti.","o":[{"id":"a","l":"Posare il Cuscino dei Sogni sotto la testa della Regina","r":"La Regina chiude gli occhi per la prima volta in secoli, e sogna.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Regina degli Incubi ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Regina degli Incubi a viso aperto","r":"Regina degli Incubi si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Svegliare la Regina con un bacio sulla fronte","to":"eFa","cost":0},{"id":"e","l":"Strapparle la corona di sogni","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Regina degli Incubi","em":"👑","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il sogno ritrovato","x":"Il Cuscino dei Sogni dà alla Regina un sogno gentile: la corte si ricompone, i frammenti tornano interi e voi uscite sereni come dopo un buon sonno.","text":"Il Cuscino dei Sogni dà alla Regina un sogno gentile: la corte si ricompone, i frammenti tornano interi e voi uscite sereni come dopo un buon sonno.","m":140},"eGood":{"t":"end","win":true,"title":"Il sogno si spegne","x":"La Regina cade e i sogni infranti si dissolvono in un lungo sospiro.","text":"La Regina cade e i sogni infranti si dissolvono in un lungo sospiro.","m":115},"eOk":{"t":"end","win":true,"title":"Un risveglio brusco","x":"La Regina si ritira dietro il baldacchino. Uscite con un sogno che non ricordate bene.","text":"La Regina si ritira dietro il baldacchino. Uscite con un sogno che non ricordate bene.","m":85},"eF1":{"t":"end","win":false,"title":"Un errore di troppo","x":"I sogni, spezzati, vi si conficcano addosso.","text":"I sogni, spezzati, vi si conficcano addosso.","m":100},"eF2":{"t":"end","win":false,"title":"Un passo falso","x":"Il trono vi riconosce come sovrano. Non era una buona idea.","text":"Il trono vi riconosce come sovrano. Non era una buona idea.","m":100},"eFa":{"t":"end","win":false,"title":"L’ultimo errore","x":"La Regina si sveglia nel peggior incubo: il vostro.","text":"La Regina si sveglia nel peggior incubo: il vostro.","m":100},"eFb":{"t":"end","win":false,"title":"Troppa fretta","x":"La Regina urla e ogni sogno infranto vi cade addosso.","text":"La Regina urla e ogni sogno infranto vi cade addosso.","m":100},"eDef":{"t"