 (91, $j${"_start":"s1","f1":{"t":"fight","e":"Anguille d’Ombra","em":"🐍","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Il primo guado","x":"La zattera si impiglia in un banco di relitti. Uno solo di voi deve scendere sul legno marcio e guidare la manovra con il palo mentre il fiume tira.","o":[{"id":"a","l":"Scegliere chi manovra il palo","who":true,"to":"f1","by":{"tank":{"r":"Il Tank pianta il palo e spinge: la zattera si libera con una scossa, ma il fiume lo schiaffeggia.","fx":{"pow":12},"fxw":{"hp":-5}},"dps":{"r":"L’eroe Danni spinge con troppa foga e il palo si spezza, ferendolo.","fxw":{"hp":-20}},"support":{"r":"Il Supporto è trascinato via dalla corrente e va soccorso.","fx":{"pow":-5},"fxw":{"hp":-40}}}},{"id":"b","l":"Spingere tutti insieme con le mani","r":"La zattera si libera lentamente, fra mille borbottii.","to":"f1","fx":{"hp":-20}}]},"f2":{"t":"fight","e":"Relitti Viventi","em":"🚢","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"Il molo di relitti","x":"La zattera approda a un molo fatto di vecchie chiglie. Un fuoco, una cesta di pane duro, una lanterna e una lavagna con scritte indecifrabili.","o":[{"id":"a","l":"Scaldarsi accanto al fuoco del molo","r":"Il fuoco vi rimette in forze.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Mangiare il pane duro della cesta","r":"Il pane è duro ma nutriente: vi sentite meglio.","stay":true,"fx":{"hp":25}},{"id":"c","l":"Decifrare la lavagna del Traghettatore","r":"Fra i graffi si legge la sequenza del passaggio: «Prima il pesce, poi la stella, in ultimo il remo». Prendete nota.","stay":true,"fx":{"flag":"indizio"}},{"id":"x","l":"Lasciare la stanza e proseguire","r":"Vi lasciate la sala alle spalle e scendete più a fondo.","to":"f2"},{"id":"z","l":"Staccare la lanterna dal molo","to":"eF2"}]},"f3":{"t":"fight","e":"Gabbiani del Rimpianto","em":"🕊️","m":1.2,"k":"e","w":"fin","l":"eDef"},"fk3":{"t":"fight","e":"Gabbiani del Rimpianto (allarme)","em":"🕊️","m":1.3,"k":"e","w":"f3","l":"eDef"},"s3":{"t":"lock","n":"La chiusa dei mondi","x":"La chiusa del fiume ha cinque ruote: tre vanno girate nell’ordine che il Traghettatore ha scritto.","sym":["🐟","⭐","🛶","⚓","🕯️"],"code":[0,1,2],"tries":3,"ok":"f3","ko":"fk3","okfx":{"flag":"key","pow":8},"kofx":{"hp":-10},"rok":"La chiusa si apre in un gorgoglio e il Remo di Cristallo emerge dall’acqua, lucente.","rko":"Le ruote sbagliate girano al contrario e il fiume si increspa.","h":{"if":"indizio","t":"La lavagna del Traghettatore dice: «pesce», poi «stella», poi «remo»."}},"fin":{"t":"scene","n":"La foce senza mare","x":"Il Traghettatore dei Mondi guida la zattera verso una foce che non sfocia mai. I suoi remi sono spezzati, e il suo sguardo è fisso sull’orizzonte.","o":[{"id":"a","l":"Porgere il Remo di Cristallo al Traghettatore","r":"Il Traghettatore afferra il Remo e per un istante riconosce la foce.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Traghettatore dei Mondi ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Traghettatore dei Mondi a viso aperto","r":"Traghettatore dei Mondi si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Chiedere al Traghettatore dove porta questa zattera","to":"eFa","cost":0},{"id":"e","l":"Spezzare l’ultimo remo del Traghettatore","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Traghettatore dei Mondi","em":"🚣","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"La foce trovata","x":"Il Remo di Cristallo guida la zattera alla foce vera: il Traghettatore approda finalmente e i mondi perduti, uno ad uno, trovano casa.","text":"Il Remo di Cristallo guida la zattera alla foce vera: il Traghettatore approda finalmente e i mondi perduti, uno ad uno, trovano casa.","m":140},"eGood":