 (93, $j${"_start":"s1","f1":{"t":"fight","e":"Monaci Volanti","em":"🧘","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Il chiostro sospeso","x":"Il chiostro è sospeso su una nuvola. Un portone si chiude da solo, un monaco volante sbarra il passo e un corrimano è in procinto di cedere.","o":[{"id":"a","l":"Il Tank sostiene il portone che si chiude e lascia passare gli altri","r":"Il portone si ferma sulle sue spalle e il gruppo passa.","role":"tank","to":"f1","fx":{"pow":12,"hp":-10}},{"id":"b","l":"Un eroe Danni disarma il monaco volante con un colpo ben calibrato","r":"Il monaco cade in una nuvola morbida e tace.","role":"dps","to":"f1","fx":{"pow":15,"hp":-15}},{"id":"c","l":"Il Supporto sistema il corrimano e dà al gruppo un indizio sul gong","r":"Il corrimano regge e sul retro trovate una scritta: la sequenza del gong.","role":"support","to":"f1","fx":{"pow":10,"hp":15}},{"id":"d","l":"Passare sul corrimano a piedi, in equilibrio","chk":{"s":"des","b":40,"ok":"f1","ko":"f1","okfx":{"pow":8},"kofx":{"hp":-20},"rok":"Camminate sul corrimano come su una corda: nessuno vi vede.","rko":"Un passo falso e scivolate sulla nuvola."}},{"id":"z","l":"Spaccare il portone con una spallata","to":"eF1"}]},"f2":{"t":"fight","e":"Campane Cadenti","em":"🔔","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"Il refettorio dei monaci","x":"Nel refettorio, i monaci vi offrono una tisana. Uno solo di voi deve accettare e restare a parlare con loro, sostenendo l’ospitalità senza farsi addormentare.","o":[{"id":"a","l":"Scegliere chi siede alla tavola dei monaci","who":true,"to":"f2","by":{"tank":{"r":"Il Tank siede pesante al tavolo: i monaci si offendono per il fracasso e lo allontanano.","fx":{"pow":-5},"fxw":{"hp":-40}},"dps":{"r":"L’eroe Danni beve tutto in un sorso: la tisana lo stordisce.","fxw":{"hp":-20}},"support":{"r":"Il Supporto siede con calma: i monaci si fidano e svelano come far suonare la campana.","fx":{"flag":"indizio","pow":8},"fxw":{"hp":-5}}}},{"id":"b","l":"Sedersi tutti alla tavola dei monaci","r":"I monaci ridono della vostra goffaggine e vi raccontano qualcosa.","to":"f2","fx":{"hp":-20}}]},"f3":{"t":"fight","e":"Draghi di Nebbia","em":"🐲","m":1.2,"k":"e","w":"fin","l":"eDef"},"fk3":{"t":"fight","e":"Draghi di Nebbia (allarme)","em":"🐲","m":1.3,"k":"e","w":"f3","l":"eDef"},"s3":{"t":"lock","n":"Il gong del Risveglio","x":"Il gong ha cinque disegni: tre vanno suonati nell’ordine che i monaci hanno indicato.","sym":["☁️","🔔","🏯","🧘","🌅"],"code":[1,4,2],"tries":3,"ok":"f3","ko":"fk3","okfx":{"flag":"key","pow":8},"kofx":{"hp":-10},"rok":"Il gong risuona e la Campana del Risveglio cala dal soffitto, lucente.","rko":"I disegni sbagliati rimbombano sordi e il monastero si inclina.","h":{"if":"indizio","t":"Il corrimano e i monaci indicavano: «campana», poi «alba», poi «tempio»."}},"fin":{"t":"scene","n":"La cella dell’Abate","x":"L’Abate delle Nuvole siede nella sua cella, sospesa a mezz’aria. Ha lo sguardo fisso nel vuoto e le mani incrociate sulle ginocchia.","o":[{"id":"a","l":"Suonare la Campana del Risveglio davanti all’Abate","r":"L’Abate sobbalza, come svegliato da un sogno lungo secoli.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Abate delle Nuvole ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Abate delle Nuvole a viso aperto","r":"Abate delle Nuvole si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Meditare accanto all’Abate","to":"eFa","cost":0},{"id":"e","l":"Spingere l’Abate giù dalla nuvola","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Abate delle Nuvole","em":"☁️","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il risveglio","x":"La Campana del Risveglio scioglie la promessa dell’Abate: il monastero scende dolcemente e i monaci, ridendo, toccano finalmente terra.","text":"La Campana del Risveglio scioglie la promessa dell’Abate: il monastero scende dolcemente e i monaci, ridendo, toccano finalmente terra.","m":140},"eGood":{"t":"end","win":true,"title":"La nuvola si sfalda","x":"L’Abate cade e la nuvola si disperde in pioggia. Il monastero si posa su un prato.","text":"L’Abate cade e la nuvola si disperde in pioggia. Il monastero si posa su un prato.","m":115},"eOk":{"t":"end","win":true,"title":"Una nube che resta","x":"L’Abate si ritira in meditazione. Uscite con le gambe leggere e una quiete strana.","text":"L’Abate si ritira in meditazione. Uscite con le gambe leggere e una quiete strana.","m":85},"eF1":{"t":"end","win":false,"title":"Troppa fretta","x":"Il portone è la porta del monastero e i monaci non l’apprezzano.","text":"Il portone è la porta del monastero e i monaci non l’apprezzano.","m":100},"eFa":{"t":"end","win":false,"title":"Un passo falso","x":"L’Abate vi ascolta. E non vi lascia più andare.","text":"L’Abate vi ascolta. E non vi lascia più andare.","m":100},"eFb":{"t":"end","win":false,"title":"Una scelta fatale","x":"L’Abate cade verso terra. E trascina con sé il monastero.","text":"L’Abate cade verso terra. E trascina con sé il monastero.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"L’Abate delle Nuvole vi trattiene per sempre fra le nuvole: la spedizione è fallita.","text":"L’Abate delle Nuvole vi trattiene per sempre fra le nuvole: la spedizione è fallita.","m":100},"_flags":{"key":"Campana del Risveglio","sigillo":"Colpo decisivo","indizio":"Indizio"}}$j$::jsonb),
 (94, $j${"_start":"s1","f1":{"t":"fight","e":"Echi Affamati","em":"🔊","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"La parete delle voci","x":"La parete dell’abisso è tappezzata di bocche che sussurrano. Per calarsi bisogna sopportare le voci. Quattro modi di scendere.","o":[{"id":"a","l":"Scendere ignorando ogni voce, un appiglio alla volta","chk":{"s":"frt","b":70,"ok":"f1","ko":"f1","okfx":{"pow":12},"kofx":{"hp":-15,"pow":-5},"rok":"Le voci si stancano di non essere ascoltate e tacciono.","rko":"Una voce vi convince a lasciare la presa per un attimo."}},{"id":"b","l":"Rispondere alle voci con una sola parola ferma","chk":{"s":"spi","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Le voci si zittiscono, colpite dalla vostra sicurezza.","rko":"Non va come speravate: vi costa fatica."}},{"id":"c","l":"Calarsi in silenzio con la fune","chk":{"s":"des","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Scendete come un’ombra: nessuna bocca vi nota.","rko":"Qualcosa va storto e il gruppo ne esce ammaccato."}},{"id":"d","l":"Resistere al frastuono che vi opprime","chk":{"s":"vig","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Il frastuono è un peso, ma lo reggete.","rko":"Il tentativo fallisce e lascia il segno."}},{"id":"z","l":"Gridare il vostro nome nell’abisso","to":"eF1"}]},"f2":{"t":"fight","e":"Voci Senza Corpo","em":"👂","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"Il ponte dei sussurri","x":"Un ponte sottile attraversa l’abisso. Una voce taglia, un’altra pesa, una terza ammalia. Ognuno ha il suo compito.","o":[{"id":"a","l":"Il Tank incassa il frastuono mentre gli altri passano","r":"Il frastuono si abbatte sullo scudo: il gruppo passa in silenzio.","role":"tank","to":"f2","fx":{"pow":12,"hp":-10}},{"id":"b","l":"Un eroe Danni spezza il sussurro che taglia il ponte","r":"Il sussurro si interrompe e il ponte regge.","role":"dps","to":"f2","fx":{"pow":15,"hp":-15}},{"id":"c","l":"Il Supporto intona la nota che calma le voci","r":"Le voci si accordano, una a una, sulla sua nota.","role":"support","to":"f2","fx":{"pow":10,"hp":15}},{"id":"d","l":"Tacere e lasciare che le voci parlino da sole","chk":{"s":"spi","b":40,"ok":"f2","ko":"f2","okfx":{"pow":8},"kofx":{"hp":-20},"rok":"Le voci si spengono, deluse dal vostro silenzio.","rko":"Le voci si accaniscono su di voi."}},{"id":"z","l":"Urlare per coprire le voci","to":"eF2"}]},"f3":{"t":"fight","e":"Sussurri Taglienti","em":"🗣️","m":1.2,"k":"e","w":"fin","l":"eDef"},"s3":{"t":"scene","n":"La grotta del Diapason","x":"In una grotta riecheggia un suono limpido. Un banco di pietra, una vasca d’acqua, un mucchio di piume e, appeso al soffitto, il Diapason d’Ossidiana.","o":[{"id":"a","l":"Bere dalla vasca d’acqua silenziosa","r":"L’acqua ha un sapore di quiete: vi rimette in sesto.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Dormire un po’ sul mucchio di piume","r":"Le piume smorzano ogni eco: dormite bene.","stay":true,"fx":{"hp":25}},{"id":"c","l":"Ascoltare l’eco del Diapason","r":"L’eco del Diapason è chiaro: lo seguite con le orecchie, prendendone la misura.","stay":true,"fx":{"flag":"key"}},{"id":"x","l":"Lasciare la stanza e proseguire","r":"Vi lasciate la sala alle spalle e scendete più a fondo.","to":"f3"},{"id":"z","l":"Colpire il Diapason con il pomo della spada","to":"eF3"}]},"fin":{"t":"scene","n":"Il fondo dell’abisso","x":"L’Eco Primordiale è una sagoma di vibrazioni sul fondo del baratro. Il suo grido è sempre quello, e torna sempre uguale.","o":[{"id":"a","l":"Percuotere il Diapason d’Ossidiana accanto all’Eco","r":"La nota pura si sovrappone all’Eco e per un istante la zittisce.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Eco Primordiale ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Eco Primordiale a viso aperto","r":"Eco Primordiale si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Gridare più forte dell’Eco","to":"eFa","cost":0},{"id":"e","l":"Cercare di tapparle la bocca","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Eco Primordiale","em":"🔊","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il silenzio vero","x":"Il Diapason d’Ossidiana dà all’Eco la nota finale: la sua voce si estingue in un respiro e l’abisso, per la prima volta, tace.","text":"Il Diapason d’Ossidiana dà all’Eco la nota finale: la sua voce si estingue in un respiro e l’abisso, per la prima volta, tace.","m":140},"eGood":{"t":"end","win":true,"title":"L’eco si spegne","x":"L’Eco cade nel suo stesso silenzio. L’abisso smette di rispondere.","text":"L’Eco cade nel suo stesso silenzio. L’abisso smette di rispondere.","m":115},"eOk":{"t":"end","win":true,"title":"Un’eco lontana","x":"L’Eco si ritira nel fondo. Risalite con le orecchie che fischiano e una voce nella testa.","text":"L’Eco si ritira nel fondo. Risalite con le orecchie che fischiano e una voce nella testa.","m":85},"eF1":{"t":"end","win":false,"title":"Una trappola mortale","x":"L’abisso lo ripete. E lo riempie di rabbia.","text":"L’abisso lo ripete. E lo riempie di rabbia.","m":100},"eF2":{"t":"end","win":false,"title":"Un errore di troppo","x":"Le voci tornano moltiplicate e vi sommergono.","text":"Le voci tornano moltiplicate e vi sommergono.","m":100},"eF3":{"t":"end","win":false,"title":"Un passo falso","x":"Il Diapason risuona e l’abisso intero risponde.","text":"Il Diapason risuona e l’abisso intero risponde.","m":100},"eFa":{"t":"end","win":false,"title":"Una scelta fatale","x":"L’Eco vi risponde moltiplicato per mille.","text":"L’Eco vi risponde moltiplicato per mille.","m":100},"eFb":{"t":"end","win":false,"title":"L’ultimo errore","x":"L’Eco è tutto il baratro, e il baratro vi stringe.","text":"L’Eco è tutto il baratro, e il baratro vi stringe.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"L’Eco Primordiale vi inghiotte nel suo grido: la spedizione è fallita.","text":"L’Eco Primordiale vi inghiotte nel suo grido: la spedizione è fallita.","m":100},"_flags":{"key":"Diapason d’Ossidiana","sigillo":"Colpo decisivo"}}$j$::jsonb),
 (95, $j${"_start":"s1","f1":{"t":"fight","e":"Globuli Guardiani","em":"🩸","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Le prime arterie","x":"Le pareti si gonfiano e si sgonfiano. Una sorgente di linfa, una sacca di nutrimento, un nodo di fibre. In fondo, un ventricolo chiuso.","o":[{"id":"a","l":"Bere la linfa dalla sorgente tiepida","r":"La linfa è dolce e vi rimette in sesto.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Aprire la sacca di nutrimento e mangiare","r":"La sacca è un alimento ricco: sentite il vigore tornare.","stay":true,"fx":{"hp":25}},{"id":"c","l":"Ascoltare il battito del labirinto per capirne il ritmo","r":"Il battito vi svela il ritmo del labirinto: sapete dove mettere i piedi.","stay":true,"fx":{"pow":10}},{"id":"x","l":"Uscire dalla stanza","r":"Un ultimo sguardo indietro, poi si va.","to":"f1"},{"id":"z","l":"Pugnalare una parete del labirinto","to":"eF1"}]},"f2":{"t":"fight","e":"Tendini Strangolatori","em":"🪢","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"Il nodo dei tendini","x":"Un nodo di tendini sbarra un corridoio. Soltanto uno di voi può sciogliere il nodo senza attivare il labirinto: serve pazienza o forza, e la scelta non è semplice.","o":[{"id":"a","l":"Scegliere chi scioglie il nodo di tendini","who":true,"to":"f2","by":{"tank":{"r":"Il Tank afferra il nodo e lo scioglie con forza controllata: i tendini cedono senza reagire.","fx":{"pow":12},"fxw":{"hp":-5}},"dps":{"r":"L’eroe Danni taglia il nodo di netto e i tendini rispondono con una stretta.","fx":{"pow":-5},"fxw":{"hp":-40}},"support":{"r":"Il Supporto tenta di sciogliere il nodo, ma il labirinto lo percepisce e lo stringe.","fxw":{"hp":-20}}}},{"id":"b","l":"Sciogliere il nodo tutti insieme, un filo ciascuno","r":"Il labirinto sbuffa e il nodo si scioglie, lasciandovi un po’ ammaccati.","to":"f2","fx":{"hp":-20}}]},"f3":{"t":"fight","e":"Cellule Ribelli","em":"🦠","m":1.2,"k":"e","w":"fin","l":"eDef"},"s3":{"t":"scene","n":"Il ventricolo","x":"Il ventricolo è una camera dalla Valvola Dorata, che si apre e si chiude a ritmo. Quattro modi di arrivarci prima che si richiuda.","o":[{"id":"a","l":"Scattare nel momento in cui la valvola si apre","chk":{"s":"des","b":70,"ok":"f3","ko":"f3","okfx":{"flag":"key","pow":8},"kofx":{"hp":-15,"pow":-5},"rok":"Siete dentro prima che si richiuda: la Valvola Dorata è vostra.","rko":"La valvola si chiude un istante troppo presto e vi stringe."}},{"id":"b","l":"Tenere aperta la valvola con le mani","chk":{"s":"for","b":50,"ok":"f3","ko":"f3","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"La valvola si piega e vi lascia passare.","rko":"Qualcosa va storto e il gruppo ne esce ammaccato."}},{"id":"c","l":"Attraversare il flusso di sangue che esce dalla valvola","chk":{"s":"vig","b":50,"ok":"f3","ko":"f3","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Il flusso vi spinge, ma lo reggete.","rko":"Il tentativo fallisce e lascia il segno."}},{"id":"d","l":"Sincronizzare il vostro respiro con il battito","chk":{"s":"spi","b":50,"ok":"f3","ko":"f3","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"La valvola si apre al vostro ritmo.","rko":"Sbagliate il momento: pagate un prezzo in forze."}},{"id":"z","l":"Tagliare la valvola con la spada","to":"eF3"}]},"fin":{"t":"scene","n":"Il centro pulsante","x":"Il Cuore del Labirinto batte al centro di una grande camera, circondato da vasi che pulsano. Una valvola manca, e il battito è irregolare.","o":[{"id":"a","l":"Inserire la Valvola Dorata nel Cuore","r":"Il battito si regolarizza: per un istante il Cuore sembra sollevato.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Cuore del Labirinto ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Cuore del Labirinto a viso aperto","r":"Cuore del Labirinto si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Accarezzare il Cuore per calmarlo","to":"eFa","cost":0},{"id":"e","l":"Strappare un vaso dal Cuore","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Cuore del Labirinto","em":"🫀","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il battito regolare","x":"La Valvola Dorata riporta il Cuore a un ritmo gentile: il labirinto si rilassa, le pareti si fanno quiete e voi uscite fra corridoi sereni.","text":"La Valvola Dorata riporta il Cuore a un ritmo gentile: il labirinto si rilassa, le pareti si fanno quiete e voi uscite fra corridoi sereni.","m":140},"eGood":{"t":"end","win":true,"title":"Il cuore si ferma","x":"Il Cuore si arresta e il labirinto si affloscia piano. Le pareti sono fredde.","text":"Il Cuore si arresta e il labirinto si affloscia piano. Le pareti sono fredde.","m":115},"eOk":{"t":"end","win":true,"title":"Un battito irregolare","x":"Il Cuore si ritira fra i vasi. Uscite con la sensazione di aver lasciato un po’ del vostro battito.","text":"Il Cuore si ritira fra i vasi. Uscite con la sensazione di aver lasciato un po’ del vostro battito.","m":85},"eF1":{"t":"end","win":false,"title":"Un errore di troppo","x":"Il labirinto sanguina, e si arrabbia.","text":"Il labirinto sanguina, e si arrabbia.","m":100},"eF3":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il labirinto urla e il ventricolo si chiude per sempre.","text":"Il labirinto urla e il ventricolo si chiude per sempre.","m":100},"eFa":{"t":"end","win":false,"title":"L’ultimo errore","x":"Il Cuore non conosce carezze: vi stringe in un battito.","text":"Il Cuore non conosce carezze: vi stringe in un battito.","m":100},"eFb":{"t":"end","win":false,"title":"Troppa fretta","x":"Il Cuore sanguina e il labirinto intero risponde.","text":"Il Cuore sanguina e il labirinto intero risponde.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Cuore del Labirinto vi assorbe nelle sue pareti: la spedizione è fallita.","text":"Il Cuore del Labirinto vi assorbe nelle sue pareti: la spedizione è fallita.","m":100},"_flags":{"key":"Valvola Dorata","sigillo":"Colpo decisivo"}}$j$::jsonb),
 (96, $j${"_start":"s1","f1":{"t":"fight","e":"Draghetti di Guardia","em":"🐉","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Il portone del bastione","x":"Il portone è sbarrato da una trave di scaglie. Uno solo di voi può reggere il peso e spingerla via mentre i draghetti di guardia osservano dalle mura.","o":[{"id":"a","l":"Scegliere chi spinge la trave del portone","who":true,"to":"f1","by":{"tank":{"r":"Il Tank pianta i piedi e spinge: la trave cede con un gemito e il portone si apre.","fx":{"pow":12},"fxw":{"hp":-5}},"dps":{"r":"L’eroe Danni colpisce la trave con troppa foga e le scaglie schizzano ovunque, ferendolo.","fxw":{"hp":-20}},"support":{"r":"Il Supporto tenta di spingere, ma la trave non si muove e i draghetti iniziano a sputare fiamma.","fx":{"pow":-5},"fxw":{"hp":-40}}}},{"id":"b","l":"Spingere tutti insieme la trave","r":"Con uno sforzo comune la trave cede, ma i draghetti vi accolgono con qualche fiammella.","to":"f1","fx":{"hp":-20}}]},"f2":{"t":"fight","e":"Cavalieri del Drago","em":"🛡️","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"Il cortile d’armi","x":"Un cortile con rastrelliere vuote, un focolare acceso e un abbeveratoio. Su una tavola di pietra sono incisi i nomi dei draghi caduti.","o":[{"id":"a","l":"Sedersi al focolare a riposare","r":"Il focolare vi scalda le ossa.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Lucidare un’armatura abbandonata e indossarla","r":"L’armatura vi sta come un guanto: sentite la forza di chi la portava.","stay":true,"fx":{"hp":25}},{"id":"c","l":"Leggere i nomi dei caduti sulla tavola","r":"I nomi sono molti, e vi spingono a portare a termine la missione.","stay":true,"fx":{"pow":10}},{"id":"d","l":"Bere all’abbeveratoio dei draghi","r":"L’acqua è fresca: vi ristora.","stay":true,"fx":{"pow":15,"hp":-20}},{"id":"x","l":"Salire alla torre del Re","r":"Salite la torre, gradino dopo gradino.","to":"f2"},{"id":"z","l":"Suonare l’allarme del bastione","to":"eF2"}]},"f3":{"t":"fight","e":"Wyvern Corazzate","em":"🦎","m":1.2,"k":"e","w":"fin","l":"eDef"},"s3":{"t":"scene","n":"La torre del Re","x":"La torre è difesa da tre ostacoli: una balestra sulla soglia, un portale incantato e una sentinella che non dorme mai. Ognuno ha il suo compito.","o":[{"id":"a","l":"Il Tank incassa i dardi della balestra mentre gli altri salgono","r":"I dardi si spezzano sul suo scudo e il gruppo sale indisturbato.","role":"tank","to":"f3","fx":{"pow":12,"hp":-10}},{"id":"b","l":"Un eroe Danni abbatte la sentinella con un colpo secco","r":"La sentinella cade con un tonfo e la torre si apre.","role":"dps","to":"f3","fx":{"pow":15,"hp":-15}},{"id":"c","l":"Il Supporto scioglie l’incantesimo del portale","r":"Il portale si dissolve in un sospiro e le scale si aprono.","role":"support","to":"f3","fx":{"flag":"key","hp":15}},{"id":"d","l":"Salire di corsa ignorando i dardi","chk":{"s":"frt","b":40,"ok":"f3","ko":"f3","okfx":{"flag":"key"},"kofx":{"hp":-20},"rok":"Qualche dardo vi sfiora, ma la Corona di Scaglie è a portata di mano.","rko":"Un dardo vi coglie e vi ferma sulle scale."}},{"id":"z","l":"Bussare alla porta del Re","to":"eF3"}]},"fin":{"t":"scene","n":"La sala del trono di scaglie","x":"Il Re dei Draghi Esuli siede su un trono di scaglie, la testa china. Una corona di scaglie, ormai spezzata, riposa sul suo ginocchio.","o":[{"id":"a","l":"Rimettere sul capo del Re la Corona di Scaglie","r":"La Corona si ricompone e il Re solleva lo sguardo, ricordando di essere un sovrano.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Re dei Draghi Esuli ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Re dei Draghi Esuli a viso aperto","r":"Re dei Draghi Esuli si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Rendere omaggio al Re con un lungo inchino","to":"eFa","cost":0},{"id":"e","l":"Sfilare la corona dal ginocchio del Re","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Re dei Draghi Esuli","em":"🐲","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il ritorno dei draghi","x":"La Corona di Scaglie restituisce al Re la sua stirpe: i draghi esuli spiccano il volo dal bastione e il cielo, dopo secoli, torna a riempirsi di ali.","text":"La Corona di Scaglie restituisce al Re la sua stirpe: i draghi esuli spiccano il volo dal bastione e il cielo, dopo secoli, torna a riempirsi di ali.","m":140},"eGood":{"t":"end","win":true,"title":"Il trono vuoto","x":"Il Re cade e la sua corona si frantuma. Il bastione tace.","text":"Il Re cade e la sua corona si frantuma. Il bastione tace.","m":115},"eOk":{"t":"end","win":true,"title":"Una fiamma bassa","x":"Il Re si ritira nella torre. Uscite con le orecchie che fischiano e una vittoria amara.","text":"Il Re si ritira nella torre. Uscite con le orecchie che fischiano e una vittoria amara.","m":85},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il corno suona e ogni difensore si desta.","text":"Il corno suona e ogni difensore si desta.","m":100},"eF3":{"t":"end","win":false,"title":"L’ultimo errore","x":"Il Re dei Draghi Esuli apre. Non era ciò che sperava.","text":"Il Re dei Draghi Esuli apre. Non era ciò che sperava.","m":100},"eFa":{"t":"end","win":false,"title":"Troppa fretta","x":"Il Re vi riconosce suoi sudditi per sempre.","text":"Il Re vi riconosce suoi sudditi per sempre.","m":100},"eFb":{"t":"end","win":false,"title":"Una trappola mortale","x":"Il Re ruggisce: sono scaglie, ma sono la sua vita.","text":"Il Re ruggisce: sono scaglie, ma sono la sua vita.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Re dei Draghi Esuli vi incenerisce sulle mura: la spedizione è fallita.","text":"Il Re dei Draghi Esuli vi incenerisce sulle mura: la spedizione è fallita.","m":100},"_flags":{"key":"Corona di Scaglie","sigillo":"Colpo decisivo"}}$j$::jsonb),
 (97, $j${"_start":"s1","_clock":6,"_late":"fL","_latetxt":"Il gong dell’Imperatore risuona e le guardie sovrane vi circondano: il tempo delle esitazioni è finito.","f1":{"t":"fight","e":"Guardie Imperiali","em":"⚔️","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"La via dei cento troni","x":"Una lunga via di troni vuoti, uno per imperatore. Ogni trono suggerisce una scelta: sedersi, osservare, pregare. Sullo sfondo un portone di marmo, e il tempo stringe.","o":[{"id":"a","l":"Sedersi per un attimo sul trono di un imperatore saggio","r":"Un’eco di saggezza vi attraversa e vi rende più saldi.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Rubare il mantello da un trono dimenticato","r":"Il mantello è caldo di regalità: sentite la forza di comando.","stay":true,"fx":{"hp":25}},{"id":"c","l":"Dissetarsi alla fontana imperiale","r":"La fontana è fresca e vi rimette in sesto.","stay":true,"fx":{"pow":10}},{"id":"d","l":"Leggere l’iscrizione sui gradini del portone","r":"L’iscrizione dice come valutare il valore di un imperatore: ne ricavate una prova di ingegno.","stay":true,"fx":{"pow":15,"hp":-20}},{"id":"e","l":"Farsi un inchino davanti a un trono maestoso","r":"Il trono vi riconosce e vi benedice con una scintilla di coraggio.","stay":true,"fx":{"pow":5,"hp":10}},{"id":"x","l":"Avanzare verso la sala dello Scettro","r":"Raggiungete il portone di marmo.","to":"f1"},{"id":"z","l":"Strappare una gemma da un trono","to":"eF1"}]},"f2":{"t":"fight","e":"Consiglieri d’Ombra","em":"🕴️","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"La sala dello Scettro","x":"Lo Scettro Imperiale è su un piedistallo circondato da quattro statue di imperatori. Ognuna sorveglia con un proprio tipo di prova.","o":[{"id":"a","l":"Rispondere all’enigma dell’imperatrice con parole di saggezza","chk":{"s":"spi","b":70,"ok":"f2","ko":"f2","okfx":{"flag":"indizio","pow":8},"kofx":{"hp":-15,"pow":-5},"rok":"L’imperatrice sorride e lascia che prendiate lo Scettro.","rko":"L’imperatrice scuote il capo e vi respinge."}},{"id":"b","l":"Spostare l’imperatore di pietra che copre il piedistallo","chk":{"s":"for","b":50,"ok":"f2","ko":"f2","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"La statua si sposta e lo Scettro è libero.","rko":"Sbagliate il momento: pagate un prezzo in forze."}},{"id":"c","l":"Sgusciare fra le statue senza svegliarle","chk":{"s":"des","b":50,"ok":"f2","ko":"f2","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Passate come un’ombra: nessuna statua vi nota.","rko":"Non basta: serve un piano migliore, e intanto si soffre."}},{"id":"d","l":"Resistere allo sguardo severo degli imperatori","chk":{"s":"frt","b":50,"ok":"f2","ko":"f2","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Lo sguardo vi pesa, ma lo reggete.","rko":"Non va come speravate: vi costa fatica."}},{"id":"z","l":"Sedersi sul trono che non vi spetta","to":"eF2"}]},"f3":{"t":"fight","e":"Statue Imperatrici","em":"🗿","m":1.2,"k":"e","w":"fin","l":"eDef"},"fk3":{"t":"fight","e":"Statue Imperatrici (allarme)","em":"🗿","m":1.3,"k":"e","w":"f3","l":"eDef"},"s3":{"t":"lock","n":"Il sigillo del portone","x":"Il portone del trono ha cinque stemmi: tre vanno premuti nell’ordine dell’iscrizione.","sym":["🦅","🦁","🐉","🐺","🐍"],"code":[3,2,1],"tries":3,"ok":"f3","ko":"fk3","okfx":{"flag":"key","pow":8},"kofx":{"hp":-10},"rok":"Il portone si apre e dal fondo della sala risplende il trono, mentre lo Scettro Imperiale vi viene incontro.","rko":"Gli stemmi sbagliati si anneriscono e il portone vi risponde con un ruggito.","h":{"if":"indizio","t":"L’iscrizione ricorda gli imperatori in quest’ordine: «lupo», poi «drago», poi «leone»."}},"fL":{"t":"fight","e":"Guardie Sovrane","em":"⚔️","m":1.5,"k":"e","w":"fin","l":"eDef"},"fin":{"t":"scene","n":"Il trono dei cento volti","x":"L’Imperatore Cento-Volti siede sul trono centrale: i suoi cento volti sono tutti rivolti verso di voi e parlano insieme.","o":[{"id":"a","l":"Porgere lo Scettro Imperiale ai cento volti","r":"I volti tacciono tutti insieme: lo Scettro dà la parola a uno solo.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Imperatore Cento-Volti ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Imperatore Cento-Volti a viso aperto","r":"Imperatore Cento-Volti si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Sedersi accanto all’Imperatore","to":"eFa","cost":0},{"id":"e","l":"Spezzare lo scettro dell’Imperatore","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Imperatore Cento-Volti","em":"🎭","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Un solo imperatore","x":"Lo Scettro Imperiale dà il comando a un volto solo: l’Imperatore ritrova la sua unità, si inchina e il trono, finalmente, ha un solo padrone.","text":"Lo Scettro Imperiale dà il comando a un volto solo: l’Imperatore ritrova la sua unità, si inchina e il trono, finalmente, ha un solo padrone.","m":140},"eGood":{"t":"end","win":true,"title":"I volti tacciono","x":"L’Imperatore cade dal trono e i volti si spengono uno ad uno. La sala tace.","text":"L’Imperatore cade dal trono e i volti si spengono uno ad uno. La sala tace.","m":115},"eOk":{"t":"end","win":true,"title":"Una corona incerta","x":"L’Imperatore si ritira nell’ombra. Uscite con un nome che non ricordate di aver ricevuto.","text":"L’Imperatore si ritira nell’ombra. Uscite con un nome che non ricordate di aver ricevuto.","m":85},"eF1":{"t":"end","win":false,"title":"Una scelta fatale","x":"La statua imperatrice si anima.","text":"La statua imperatrice si anima.","m":100},"eF2":{"t":"end","win":false,"title":"L’ultimo errore","x":"Cento imperatori si alzano insieme.","text":"Cento imperatori si alzano insieme.","m":100},"eFa":{"t":"end","win":false,"title":"Una trappola mortale","x":"I cento volti vi eleggono. Non era una buona notizia.","text":"I cento volti vi eleggono. Non era una buona notizia.","m":100},"eFb":{"t":"end","win":false,"title":"Un errore di troppo","x":"I cento volti urlano: nessuno li ha mai contraddetti.","text":"I cento volti urlano: nessuno li ha mai contraddetti.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"L’Imperatore Cento-Volti vi condanna con cento voci: la spedizione è fallita.","text":"L’Imperatore Cento-Volti vi condanna con cento voci: la spedizione è fallita.","m":100},"_flags":{"key":"Scettro Imperiale","sigillo":"Colpo decisivo","indizio":"Indizio"}}$j$::jsonb),
 (98, $j${"_start":"s1","f1":{"t":"fight","e":"Ombre Senza Forma","em":"⚫","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Il ciglio del nulla","x":"Il sentiero finisce in un ciglio: oltre c’è il vuoto. Un’ombra sbarra il passo, un pensiero cancellato ammalia e un tratto di strada svanisce a ogni passo.","o":[{"id":"a","l":"Il Tank regge l’ombra che sbarra il passo e lascia passare gli altri","r":"L’ombra si schianta contro lo scudo e svanisce.","role":"tank","to":"f1","fx":{"pow":12,"hp":-10}},{"id":"b","l":"Un eroe Danni cancella il pensiero ammaliatore con un colpo secco","r":"Il pensiero si dissolve e la strada ritorna.","role":"dps","to":"f1","fx":{"pow":15,"hp":-15}},{"id":"c","l":"Il Supporto ricorda ad alta voce la strada che svanisce","r":"Il percorso si fissa nella memoria del gruppo.","role":"support","to":"f1","fx":{"pow":10,"hp":15}},{"id":"d","l":"Ricordarsi con forza di essere qualcuno","chk":{"s":"spi","b":40,"ok":"f1","ko":"f1","okfx":{"pow":8},"kofx":{"hp":-20},"rok":"Il vuoto vi cerca e non vi trova: resta il vostro nome.","rko":"Il vuoto vi trova e vi cancella un ricordo."}},{"id":"z","l":"Camminare nel vuoto a occhi chiusi","to":"eF1"}]},"f2":{"t":"fight","e":"Pensieri Cancellati","em":"💭","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"La prima stanza vuota","x":"Una stanza senza pareti vi accoglie: nessun suono, nessuna luce. Soltanto uno di voi può reggere il silenzio e fare da bussola al gruppo.","o":[{"id":"a","l":"Scegliere chi fa da bussola al gruppo","who":true,"to":"f2","by":{"tank":{"r":"Il Tank cammina rumorosamente e il vuoto lo avvolge: perde l’orientamento.","fx":{"pow":-5},"fxw":{"hp":-40}},"dps":{"r":"L’eroe Danni procede a scatti, e il vuoto ne approfitta per cancellargli qualche passo.","fxw":{"hp":-20}},"support":{"r":"Il Supporto resta in ascolto e trova il filo del silenzio: guida il gruppo senza esitazioni.","fx":{"pow":12},"fxw":{"hp":-5}}}},{"id":"b","l":"Muoversi tenendosi per mano nel vuoto","r":"Vi perdete un poco, ma vi ritrovate.","to":"f2","fx":{"hp":-20}}]},"f3":{"t":"fight","e":"Tracce del Nulla","em":"🌑","m":1.2,"k":"e","w":"fin","l":"eDef"},"s3":{"t":"scene","n":"La stella spenta","x":"La Stella Spenta galleggia nel nulla, fredda come un pensiero dimenticato. Quattro modi di raggiungerla.","o":[{"id":"a","l":"Riaccendere in voi il ricordo di una luce","chk":{"s":"spi","b":70,"ok":"f3","ko":"f3","okfx":{"flag":"key","pow":8},"kofx":{"hp":-15,"pow":-5},"rok":"Il ricordo illumina il tragitto e la Stella Spenta è vostra.","rko":"Il ricordo si spegne e il vuoto vi stringe."}},{"id":"b","l":"Resistere all’assenza di ogni suono","chk":{"s":"frt","b":50,"ok":"f3","ko":"f3","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Il silenzio vi pesa, ma lo reggete.","rko":"Non basta: serve un piano migliore, e intanto si soffre."}},{"id":"c","l":"Respirare nel vuoto che non ha aria","chk":{"s":"vig","b":50,"ok":"f3","ko":"f3","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Respirate comunque: il vuoto si piega.","rko":"Non va come speravate: vi costa fatica."}},{"id":"d","l":"Saltare da un frammento di realtà a un altro","chk":{"s":"des","b":50,"ok":"f3","ko":"f3","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Vi muovete di frammento in frammento: la stella è a portata di mano.","rko":"Qualcosa va storto e il gruppo ne esce ammaccato."}},{"id":"z","l":"Gridare il vostro nome al nulla","to":"eF3"}]},"fin":{"t":"scene","n":"Il centro del nulla","x":"Il Vuoto Pensante non ha forma, ma vi fissa. Davanti a lui, un solo punto ancora buio chiede una luce.","o":[{"id":"a","l":"Accendere la Stella Spenta davanti al Vuoto","r":"La Stella arde per un istante, e il Vuoto la guarda stupito: non aveva mai visto una luce.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"cost":0},{"id":"b","l":"Prendere fiato prima dello scontro finale","r":"Il riposo cura le ferite, ma Il Vuoto Pensante ha già visto ogni vostra mossa.","to":"fb","fx":{"hp":35,"pow":-12},"cost":0},{"id":"c","l":"Sfidare Il Vuoto Pensante a viso aperto","r":"Il Vuoto Pensante si prepara: lo scontro comincia.","to":"fb","cost":0},{"id":"d","l":"Fargli compagnia nel nulla","to":"eFa","cost":0},{"id":"e","l":"Cercare di riempire il Vuoto con le vostre armi","to":"eFb","cost":0}]},"fb":{"t":"fight","e":"Il Vuoto Pensante","em":"⚫","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Una luce nel nulla","x":"La Stella Spenta si accende nel vuoto: il Vuoto Pensante ha finalmente qualcosa da guardare, e il nulla, per la prima volta, ha un confine.","text":"La Stella Spenta si accende nel vuoto: il Vuoto Pensante ha finalmente qualcosa da guardare, e il nulla, per la prima volta, ha un confine.","m":140},"eGood":{"t":"end","win":true,"title":"Il vuoto si chiude","x":"Il Vuoto cade su se stesso e la soglia svanisce. Il mondo torna a esistere.","text":"Il Vuoto cade su se stesso e la soglia svanisce. Il mondo torna a esistere.","m":115},"eOk":{"t":"end","win":true,"title":"Un’assenza che resta","x":"Il Vuoto si ritira oltre la soglia. Uscite con la sensazione di aver lasciato qualcosa di indefinito dietro di voi.","text":"Il Vuoto si ritira oltre la soglia. Uscite con la sensazione di aver lasciato qualcosa di indefinito dietro di voi.","m":85},"eF1":{"t":"end","win":false,"title":"L’ultimo errore","x":"Il vuoto è il vostro prossimo passo.","text":"Il vuoto è il vostro prossimo passo.","m":100},"eF3":{"t":"end","win":false,"title":"Una trappola mortale","x":"Il nulla lo accoglie. E lo tiene.","text":"Il nulla lo accoglie. E lo tiene.","m":100},"eFa":{"t":"end","win":false,"title":"Un errore di troppo","x":"Il Vuoto accoglie la vostra compagnia. Per sempre.","text":"Il Vuoto accoglie la vostra compagnia. Per sempre.","m":100},"eFb":{"t":"end","win":false,"title":"Un passo falso","x":"Il Vuoto le assorbe, una a una.","text":"Il Vuoto le assorbe, una a una.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Vuoto Pensante vi cancella dalla mappa: la spedizione è fallita.","text":"Il Vuoto Pensante vi cancella dalla mappa: la spedizione è fallita.","m":100},"_flags":{"key":"Stella Spenta","sigillo":"Colpo decisivo"}}$j$::jsonb),
 (99, $j${"_start":"s1","f1":{"t":"fight","e":"Scintille Creatrici","em":"✨","m":1.0,"k":"n","w":"s2","l":"eDef"},"s1":{"t":"scene","n":"Il canale di fusione","x":"Un canale di metallo creatore taglia la fucina. Per attraversarlo, serve ingegno e sangue freddo. Quattro modi di passare.","o":[{"id":"a","l":"Saltare di incudine in incudine sopra il canale","chk":{"s":"des","b":70,"ok":"f1","ko":"f1","okfx":{"pow":12},"kofx":{"hp":-15,"pow":-5},"rok":"Le incudini vi reggono: passate senza scottature.","rko":"Un’incudine ondeggia e vi manda a un passo dalla colata."}},{"id":"b","l":"Sollevare un’incudine e usarla come ponte","chk":{"s":"for","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"L’incudine fa da ponte e il canale è alle spalle.","rko":"Non va come speravate: vi costa fatica."}},{"id":"c","l":"Resistere al calore della fusione camminando piano","chk":{"s":"vig","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Il calore vi scotta, ma la vostra tempra regge.","rko":"Qualcosa va storto e il gruppo ne esce ammaccato."}},{"id":"d","l":"Invocare l’idea del primo ponte","chk":{"s":"spi","b":50,"ok":"f1","ko":"f1","okfx":{"pow":6},"kofx":{"hp":-15,"pow":-5},"rok":"Il ponte si forma da solo: l’idea lo ha fatto.","rko":"Il tentativo fallisce e lascia il segno."}},{"id":"z","l":"Tuffarsi nel canale per attraversarlo a nuoto","to":"eF1"}]},"f2":{"t":"fight","e":"Martelli Vivi","em":"🔨","m":1.1,"k":"n","w":"s3","l":"eDef"},"s2":{"t":"scene","n":"La bottega del Fabbro","x":"Una bottega vastissima, piena di strumenti che non si sa a cosa servano. Un pozzo d’acqua, un mantice, una cesta di carbone e una cassaforte sigillata.","o":[{"id":"a","l":"Bere dal pozzo della bottega","r":"L’acqua è fresca come il primo giorno: vi rimette in sesto.","stay":true,"fx":{"pow":8}},{"id":"b","l":"Usare il mantice per ravvivare una brace","r":"La brace si ravviva e il calore vi dà coraggio.","stay":true,"fx":{"hp":25}},{"id":"c","l":"